/* NHÓM 2c — máy soi CHÍNH CÁI KIT: tự kiểm toán, tra cứu, đóng gói và phát hành (9/2026).
   Nguồn: header của scripts/qa/{gate_index,rule_lookup,version_check,package_kit,verify_release}.js */
const TERMS_GATE3 = [

{ id:'g-bug_claim', t:'bug:claim', cat:'gate',
  def:'Một phát hiện bug phải QUA MÁY trước khi được nói thành lời. Claim thiếu trường, hoặc case đã chấm product_bug mà không có claim, đều bị chặn.',
  detail:'Claim là file JSON ở <TASK_OUTPUT_DIR>/reports/bug-claims/. Bắt buộc: oracle độc lập kèm TRÍCH nguyên văn, expected và actual là giá trị, rerun ổn định ít nhất 2 lượt, tầng FE hay BE kèm phép đo, dụng cụ đọc, đường dựng fixture, và ba phản chứng. Chặn hai chiều: chiều xuôi là claim thiếu trường, chiều ngược là case chấm bug mà không có claim.',
  why:'Lỗi lặp lại do chủ repo chỉ ra 16/09/2026: agent báo phát hiện bug rồi hỏi có log không, user hỏi lại chắc chưa, agent kiểm lại rồi rút lời. Gốc là lỗi THỨ TỰ: bar khẳng định bug nằm ở phase2_04 với khoảng tám điều kiện, còn lời nói ra ở phase2_03 với hai điều kiện. Và lỗi này chưa từng được đếm, vì claim rút trước khi log thì không lên Backlog nên không vào knowledge/bugs.',
  how:['npm run bug:claim:new -- --new <TC_ID> để tạo bản nháp đủ trường.','npm run bug:claim để kiểm trước khi nói chữ bug.','npm run bug:claim:report để đếm tỉ lệ rút và phép kiểm nào bắt được.'],
  cmd:'npm run bug:claim   ·   npm run bug:claim:report',
  ex:'Ba nhóm phản chứng không phải nghĩ ra: tài liệu cũ hơn build (hạn checkout 720h so với FSD ghi 24h), dụng cụ đọc sai (lọc toast theo class gây CSDL-28776 bị Rejected), fixture dựng không tự nhiên (pipeline nhân bản không đại diện).',
  trap:'Máy đếm được ba phản chứng nhưng không đọc được ý định. Nên mỗi phản chứng phải dẫn một PHÉP ĐO có số, lệnh, endpoint hoặc đường dẫn file. Bịa một phép đo khó hơn bịa một câu.',
  src:'scripts/qa/bug_claim.js', rel:['c-forcing-function','g-gate_index','c-oracle'] },
{ id:'g-gate_friction', t:'gate:friction', cat:'gate',
  def:'SỔ MA SÁT của gate: mỗi lượt chặn, mỗi lượt ghi sổ nợ, mỗi lượt miễn trừ. Cộng quy tắc dọn, chỉ đề xuất.',
  detail:'Bốn sự kiện: `chan` · `so_no` · `mien_tru` · `bao_oan`. Ba cái đầu ghi TỰ ĐỘNG ở chỗ chúng xảy ra (`gate_tier.apTang` và `override.tao`); cái thứ tư CHỈ vào sổ khi có người khai thẳng. Append-only, nằm ở `knowledge/metrics/` là lớp PROJECT.',
  why:'Kiểm kê §1 kết luận bốn thứ "chưa đo được", ba trong bốn cùng một gốc: không nguồn nào ghi "gate X đã chặn N lần". Transcript không được track, thư mục reports của task ghi kết quả task chứ không ghi lượt bị gate chặn. Nên mọi câu về ma sát của gate đều là cảm giác.',
  cmd:'npm run gate:friction   ·   --bao-oan <gate> --ma <MÃ> --ly-do "<lý do>"',
  trap:'BÁO OAN KHÔNG suy được từ số lượt override: người ta miễn trừ cả khi gate ĐÚNG mà việc vẫn phải đi tiếp, nên suy như vậy làm một gate đúng bị kết luận là sai rồi bị nới. Và quy tắc nguy hiểm nhất là quy tắc KHÔNG được áp: gate CHƯA TỪNG ĐỎ không phải căn cứ để bỏ — chưa đỏ có thể là đang gác lớp lỗi kit chưa gặp, chưa ai chạy nó, hoặc nó HỎNG và `catch` nuốt mọi thứ (đã xảy ra với `dimension_coverage`).',
  src:'scripts/qa/gate_friction.js', rel:['g-gate_audit','g-check','c-forcing-function'] },
{ id:'g-next', t:'next', cat:'gate',
  def:'LỆNH TIẾP THEO, suy từ trạng thái artifact có thật. Làm sáu lệnh ngoài nhóm năm lệnh tìm thấy được mà không phải nhớ.',
  detail:'Đọc FILE CÓ THẬT: có profile chưa, có bản đồ hệ thống chưa, đã neo mẫu số chưa, có register và làn chưa, có case và file status chưa, sổ nợ còn mấy món, đã qua cửa nào. Gợi ý xếp theo DÒNG CHẢY của một task chứ không theo mức quan trọng, vì người đang ở bước 2 không cần nghe gợi ý của bước 5.',
  why:'Đo ở BASELINE: 55 lệnh npm khác nhau rải khắp các điểm vào, 43 lệnh gate trong chuỗi Phase 2. Đích là người dùng chỉ nhớ NĂM lệnh. Nhưng sáu lệnh còn lại vẫn cần thiết — chúng chỉ không nên cần NHỚ, nên chỗ đúng để gợi ý chúng là output của lệnh người ta vừa gõ.',
  cmd:'npm run next -- --task <KEY>   ·   --mot-dong   ·   --json',
  trap:'CHỈ GỢI Ý, không tự chạy và không tự ghi — một test quét source đòi không có `writeFileSync` lẫn `spawnSync` nào. Máy biết trạng thái nhưng không biết người đang muốn làm gì; họ có thể đang cố ý dừng giữa để rà một chỗ. Và THIẾU sổ nợ khác sổ nợ SẠCH: `so_no === null` nghĩa là chưa gate nào ghi gì, mà điều đó có thể nghĩa là chưa gate nào CHẠY.',
  src:'scripts/qa/next_command.js', rel:['g-check','g-exit_gate','g-lane'] },
{ id:'g-lane', t:'lane', cat:'gate',
  def:'HAI LÀN theo risk: `lite` cho task rủi ro thấp, `full` khi có module band High. Làn quyết ĐỘ SÂU, không quyết mức an toàn.',
  detail:'Làn do SỐ quyết: đọc `risk-register.json`, một module band High kéo cả task sang `full`, vì case của module này chạm dữ liệu và trạng thái của module khác. `band_override` của QA thắng band máy tính, nhưng override được ghi dài hạn ở `knowledge/decisions/` nên không mất dấu.',
  why:'Mở rộng 5 trục là phần đắt nhất của Phase 2. Nó đáng giá ở chỗ rủi ro cao, còn ở band Low thì chi phí lớn hơn thứ nó mua. Nhưng "cho nhẹ bớt" là cánh cửa rất dễ mở rộng dần, nên làn phải do số quyết chứ không do người chạy.',
  cmd:'npm run lane -- --task <KEY>   ·   --dat lite|full --ly-do "<lý do>"',
  trap:'UNKNOWN ⇒ `full`, KHÔNG phải `lite`: chưa đo được impact không nghĩa là impact thấp, và gộp nó vào lite làm làn nhẹ thành mặc định cho mọi task mới. Nâng lite→full luôn được; hạ full→lite ở band High thì CHẶN và không có cờ nào. Bốn thứ giữ nguyên ở cả hai làn: 13 máy T0, evidence theo luật 4, ngưỡng rerun của taxonomy, và ba cửa ra. Config cố ý KHÔNG có khoá boolean nào cho evidence hay rerun — boolean thì tắt được.',
  src:'scripts/qa/lane.js', rel:['g-check','g-exit_gate','f-risk-register'] },
{ id:'g-autofix', t:'check --fix', cat:'gate',
  def:'Tự sửa ĐỊNH DẠNG, không đổi nghĩa: alias thang Ưu tiên, `<br>` chuẩn, ký tự vô hình, tag nằm nhầm trong tiêu đề, đánh số bước lệch.',
  detail:'Mỗi luật KHAI cột nó được phép chạm, và `CAM_CHAM` là danh sách cột không luật nào được sửa nội dung: Kết quả mong đợi · Dữ liệu Test · Loại case · Tiền điều kiện. Luật duy nhất chạm được ô Expected chỉ sửa TIỀN TỐ SỐ, và nó tự chứng minh bằng cách so phần chữ trước và sau — lệch một ký tự là bỏ luật. Mỗi lượt ghi diff từng ô vào `reports/autofix.log`; `--dry-run` xem trước mà không ghi gì.',
  why:'Một phần đáng kể vi phạm mà gate bắt là lỗi định dạng thuần, không cần người đọc — nhưng mỗi cái vẫn làm một lượt chạy đỏ và người ta phải mở file sửa tay.',
  cmd:'npm run check -- --fix   ·   npm run check -- --dry-run',
  trap:'Một máy tự sửa testcase ở sai chỗ là máy GIAN LẬN THAY CHO NGƯỜI: sửa Kết quả mong đợi cho khớp cái app đang trả về thì mọi case đỏ thành xanh, và §6 bị phá bởi chính công cụ của kit. Và phải IDEMPOTENT — bản đầu không, vì `tachO` không trim nên luật khoảng trắng báo đổi mãi mãi và log đầy diff rỗng.',
  src:'scripts/qa/autofix.js', rel:['g-check','r-nocheat','g-expected_ledger'] },
{ id:'g-check', t:'check', cat:'gate',
  def:'MỘT lệnh kiểm: tự nhận phase theo artifact, parse bộ case một lượt, chạy gate của phase, in một bảng gọn.',
  detail:'Áp luôn lớp tầng: T0 chặn ngay, T1 ở `write`/`phase` chỉ cảnh báo nhưng vào sổ nợ và cửa ra sẽ chặn, đổi hành vi theo `--context`. Ba trạng thái chứ không hai: ✗ chặn · ⚠ cảnh báo · ○ không phán được, và ○ KHÔNG gộp vào "kiểm đạt".',
  why:'Đo ở `docs/v2.7.0/BASELINE.md`: chuỗi Phase 2 bảo agent chạy 43 lệnh gate, Phase 1 bảo 30, và riêng dàn gate mức repo in 16.551 byte mỗi lượt. Đích của v2.7.0 là người dùng chỉ cần nhớ 5 lệnh. Đo lại sau: 2.3k byte thay cho 12.7k của `self-review` trên cùng bộ 213 case.',
  cmd:'npm run check -- --task <KEY>   ·   --context exit   ·   --full   ·   --explain <MÃ>',
  trap:'"Một tiến trình" chỉ đạt MỘT PHẦN: 5 gate chạy trong tiến trình, 6 còn phải spawn vì chúng không có `require.main` guard hoặc không export hàm gate. Hai con số đó được IN RA, vì một lời hứa không đếm được thì không ai kiểm được. Và phải có PHÉP ĐO TƯƠNG ĐƯƠNG: tập vi phạm của `check` bằng đúng hợp của các gate chạy rời, cùng mã và cùng TC ID — một lệnh gộp bỏ sót vi phạm còn tệ hơn mười lệnh rời, vì nó làm người ta thôi chạy mười lệnh kia.',
  src:'scripts/qa/check.js', rel:['g-exit_gate','g-gate_audit','c-forcing-function'] },
{ id:'g-exit_gate', t:'exit:gate', cat:'gate',
  def:'BA CỬA RA: trước publish · trước log bug · trước chuyển Done hoặc phát hành. Mỗi đường ra ngoài kit phải qua đúng một cửa.',
  detail:'Cửa đọc sổ nợ T1 rồi chạy các máy khai trong `.agent/config/exit_gates.json`, mỗi máy kèm một câu vì sao nó thuộc cửa đó. Bản đồ để ở config chứ không trong code, vì khai trong code thì không ai kiểm toán được một cửa đã bị rút bớt máy — bớt một dòng là xong. Qua cửa thì ghi dấu vết mang BĂM của đầu vào, nên một lượt qua cửa không dùng lại được cho bộ đã đổi sau đó.',
  why:'Phân tầng ở §A1 hoãn mọi vi phạm T1 từ "chặn ngay" sang "chặn ở cửa ra". Nếu cửa ra không có thật thì đợt giảm ma sát biến thành đợt NỚI GATE: 57 máy T1 thôi chặn mà không gì chặn thay. Ba cửa này là phần giữ lời của §A1.',
  cmd:'npm run exit:gate -- --liet-ke   ·   npm run exit:gate -- --cua publish|bug|done',
  trap:'Ba trạng thái, không phải hai: ✓ đạt · ✗ chặn · ○ KHÔNG PHÁN ĐƯỢC (exit 2). Coi exit 2 là đạt thì cửa mở cho một thứ chưa ai kiểm; coi là vi phạm thì cửa chặn một task chỉ vì thiếu input không liên quan. Chính cửa ra đã phơi ra chỗ này: `expected:check` từng exit 0 khi chưa có mốc, nên bảng in dấu ✓ ngay dưới dòng nó vừa nói "đây KHÔNG phải là đạt".',
  src:'scripts/qa/exit_gate.js', rel:['g-gate_audit','c-forcing-function','r-nocheat'] },
{ id:'g-expected_ledger', t:'expected:check', cat:'gate',
  def:'CHẶN "đổi cột `Kết quả mong đợi` để case xanh" — non-negotiable §6, tầng T0.',
  detail:'Chụp mốc BĂM của expected từng case ở cửa publish, rồi so. Băm chứ không lưu nguyên văn: expected mang tên đơn vị, tên trường, có lúc cả tên người, nên lưu nguyên văn là tạo thêm một bản sao PII. Luật KHÔNG cấm đổi — đổi vì spec đổi là bình thường. Thứ bị chặn là đổi mà không ai biết, nên hợp đồng là khai một dòng lý do có nghĩa vào `reports/expected-changes.md`.',
  why:'Kiểm kê gate ngày 11/10/2026 cho thấy §6 có ba vế mà chỉ hai vế có máy: "xoá hoặc nới assertion" do `auto:review` rule `no-assert`, "hardcode data task-specific" do `package:kit` cảnh báo ở cửa phát hành, còn "đổi expected để pass" thì KHÔNG máy nào. Đó là cách gian lận rẻ nhất trong cả kit: một ô, không cần sửa code, và case đỏ thành xanh.',
  cmd:'npm run expected:snapshot   ·   npm run expected:check',
  trap:'`git diff` KHÔNG dùng được: testcase của task nằm trong `outputs/**` đã bị gitignore nên không có bản commit nào để so. Và đường né vẫn còn: sửa expected rồi chụp lại mốc thì máy không ngăn được, vì mốc là file trong `outputs/`. Máy nói rõ chuyện đó ở cả lúc chụp và lúc báo lỗi, nhưng đó là giới hạn thật.',
  src:'scripts/qa/expected_ledger.js', rel:['r-nocheat','g-result_ledger','g-auto_review'] },
{ id:'g-gate_audit', t:'gate:audit', cat:'gate',
  def:'Kiểm kê 102 máy gác để PHÂN TẦNG: máy đó chặn vào lúc nào, đã từng chặn oan chưa, có bị máy khác bắt trùng không.',
  detail:'Không tự đếm lại: nó require `gate_index` để dùng đúng một phép kiểm kê. Tầng T0 lấy từ `gate_tiers.json` do NGƯỜI khai; từ khoá chỉ còn là cột gợi ý, in ra danh sách ứng viên T0 chưa khai để rà. Thời điểm chạy (write · phase · exit · ci) suy từ bề mặt gọi, không khai tay, nên bảng tự đúng theo source.',
  why:'Phân tầng để giảm ma sát cần ba con số mà `gates:index` không có: chặn lúc nào, chặn oan bao nhiêu lần, và có trùng với máy khác không. Thiếu chúng thì "giảm ma sát" chỉ là cảm giác ai chặn nhiều quá.',
  cmd:'npm run gate:audit   ·   npm run gate:audit -- --full   ·   npm run gate:audit -- --write-tiers',
  trap:'HAI LẦN suy tầng bằng từ khoá đều thất bại. Suy từ một dòng mô tả: 66/102 máy không khớp gì, và `prompt:budget` bị xếp T0 "lộ secret" vì chữ token trong mô tả nó nghĩa là token của prompt. Suy từ cả khối header: T0 phình lên 40 máy. Nên T0 phải khai tay, và `--write-tiers` TỪ CHỐI ghi đè khối khai tay — lượt đầu của cờ đó đã xoá sạch 12 dòng T0 không một lời cảnh báo.',
  src:'scripts/qa/gate_audit.js', rel:['g-gate_index','c-forcing-function','r-nocheat'] },
{ id:'g-gate_code_pair', t:'gate:code-pair', cat:'gate',
  def:'Khoá ĐƯỜNG ĐỊNH TUYẾN của 21 mã gate T0/T1: mỗi mã khai một câu THẬT mà gate phát ra, và maCua(câu) phải trả về đúng mã đó.',
  detail:'Mã gate KHÔNG do gate gọi tên — `gate_engine.maCua()` khớp regex `khop` trong `gate_codes.json` lên CÂU THÔNG BÁO. Nên mã là thứ SUY RA từ văn bản, và nới một `khop` có thể giành mất câu của mã khác mà không gì báo. Máy còn ĐO mỗi lượt: bao nhiêu mã có spec đòi gate phát ra đúng mã đó.',
  why:'Đo 12/10/2026 trên 7.939 chuỗi literal trong scripts: 18 chuỗi khớp HAI mã hoặc hơn, trong đó có cặp hai mã T0 (`FAIL_CHUA_PHAN_TANG` + `RERUN_THIEU`). Mã nào thắng tuỳ THỨ TỰ KHAI trong file config, và người sửa đọc hướng dẫn của mã khác.',
  cmd:'npm run gate:code-pair   ·   npm run gate:code-pair:enforce',
  trap:'PHÉP ĐO ĐỘ PHỦ GIAN LẬN ĐƯỢC, và máy tự khai điều đó: nó đếm "có spec nào NHẮC câu này", không đếm "có spec nào DRIVE gate phát ra câu này". Viết một spec liệt kê cả 21 câu mẫu là đủ đẩy 2/21 lên 21/21 mà không thêm một phép đo nào. Vì vậy `gate-code-pair.spec.ts` cố ý KHÔNG nhúng câu mẫu nào.',
  src:'scripts/qa/gate_code_pair.js', rel:['g-gate_index','g-gate_audit','c-forcing-function'] },
{ id:'g-gate_selfmutate', t:'gate:selfmutate', cat:'gate',
  def:'Làm HỎNG gate một cách có kiểm soát rồi xem spec của nó có đỏ không. Mutant sống sót trên đường phán = spec yếu.',
  detail:'Bốn toán tử, mỗi cái tái hiện một lỗi THẬT đã xảy ra trong kit. Trả lại file nguyên văn kể cả khi ném giữa đường; từ chối chạm file đang sửa dở; bỏ qua gate mà spec ĐANG ĐỎ, vì lúc đó mọi kết luận là rỗng.',
  why:'Một bộ spec xanh không nói spec có bắt được gì. Nó chỉ nói hôm nay không ai làm hỏng gate. Cách duy nhất biết spec có hiệu lực là làm hỏng gate rồi xem spec có kêu.',
  cmd:'npm run gate:selfmutate   ·   --gate <tên>   ·   --liet-ke',
  trap:'CHÍNH MÁY NÀY TỪNG ĐẾM SAI BA LẦN. (1) Đột biến làm VỠ CÚ PHÁP được đếm là "bị bắt" — nhưng file không parse được thì MỌI spec đều đỏ, kể cả spec rỗng; giờ `vm.Script` làm trọng tài. (2) Toán tử thay chỗ khớp văn bản ĐẦU TIÊN, mà chỗ đó hay là hàm đọc cờ hoặc một dòng `console.log`; giờ máy khai mutant rơi vào dòng nào và tách "trên đường phán" với "ngoài đường phán". (3) "Không áp được" KHÔNG phải "đã bắt".',
  src:'scripts/qa/gate_selfmutate.js', rel:['g-gate_code_pair','c-forcing-function','r-nocheat'] },
{ id:'g-golden_check', t:'golden:check', cat:'gate',
  def:'MỐC VÀNG đóng băng đầu ra parser canonical trên bộ fixture cố định, cộng HAI phép đếm độc lập.',
  detail:'Ba fixture phủ ba bẫy đã từng làm sai số liệu: đánh số bước, ký tự (icon, mũi tên là chữ nghĩa, khoảng trắng vô hình), và một bộ tối thiểu làm mốc. Mốc gồm 17 trường mỗi case — hẹp đúng phần 30 gate tiêu thụ, KHÔNG gồm `_cells`.',
  why:'`scripts/lib/testcase` là chỗ 30 file cùng dùng: một thay đổi nhỏ ở đó đổi đầu ra của cả 30 gate một lúc. Đã xảy ra thật: một lượt đọc .xlsx đếm 194 case thành 1.179 vì ô stub `t:z` rơi vào nhánh String(ô) ra "[object Object]".',
  cmd:'npm run golden:check   ·   npm run golden:snapshot (đòi --toi-da-doi-parser)',
  trap:'SINH LẠI MỐC LÀ MỘT LỜI KHAI, không phải lệnh dọn dẹp. `--write` trần bị CHẶN: nếu nó chạy được không điều kiện thì cách rẻ nhất để làm xanh một lượt đỏ là ghi lại mốc, và lúc đó mốc chỉ còn ghi lại hiện trạng. Phép đếm thứ hai phải NGÂY THƠ — nếu nó cũng gọi `parseMarkdown` thì hai đường cùng sai một lúc và phép đối chiếu không phát hiện gì.',
  src:'scripts/qa/golden_check.js', rel:['g-canonical_drift','c-forcing-function'] },
{ id:'g-rule_coverage', t:'rule:coverage', cat:'gate',
  def:'BẢN ĐỒ luật → gate → spec: luật nào đang có máy thi hành, và luật nào chỉ nói bằng chữ.',
  detail:'Nối bằng cách tìm TÊN LỆNH trong văn bản mục luật. Mục không nối được phải có LỜI KHAI của người, một trong bốn loại: có máy mà không nhắc tên · đo được mà chưa có máy · không đo được bằng máy · không phải luật. `--check` CHẶN khi còn mục chưa ai phân loại.',
  why:'"Kit có 110 gate" nghe như một bảo đảm, trong khi nó không nói gì về việc 110 cái đó phủ đúng chỗ nào. Không chỗ nào trả lời được câu đơn giản nhất: luật nào đang có máy.',
  cmd:'npm run rule:coverage   ·   npm run rule:coverage:check',
  trap:'NHÃN THỨ TƯ LÀ CHỖ PROMPT NÓI THIẾU. §A10.7 chỉ cho hai lựa chọn: có gate, hoặc "không đo được bằng máy". §Cleanup Rules không thuộc cái nào — nó liệt kê hẳn bảng pattern và nói rõ chuyện đã xảy ra, nên quét root là phép đo hiển nhiên. Ghi nó là "không đo được" là KHAI SAI. Và giới hạn của phép nối: đòi luật canonical nhắc TÊN mọi lệnh thì 19/24 script báo oan.',
  src:'scripts/qa/rule_coverage.js', rel:['g-gate_index','g-cleanup_check','g-judge'] },
{ id:'g-cleanup_check', t:'cleanup:check', cat:'gate',
  def:'Quét file dump ad-hoc còn sót ở root repo và subfolder CẤP 1, theo đúng bảng pattern của §Cleanup Rules.',
  detail:'Phạm vi hẹp đúng như luật viết: root và cấp 1. Bỏ qua đúng bảng "Không xóa" (`outputs/`, `node_modules/`, `*.config.ts`, `package.json`). Khai MẪU SỐ đã xét, và exit 2 khi xét 0 file.',
  why:'Máy này do `rule:coverage` tìm ra: §Cleanup Rules là mục luật DUY NHẤT thuộc loại "đo được mà chưa có máy". Luật nói rõ chuyện đã xảy ra — nhiều file `scratch_*` dump API và swagger sót ở root sau một task, chưa gitignore.',
  cmd:'npm run cleanup:check   ·   npm run cleanup:check:enforce',
  trap:'`secret:scan` KHÔNG thay được: nó tìm secret trong NỘI DUNG file. Một dump swagger không chứa secret nào vẫn là rác lọt lưới, và nó thường chứa email/SĐT trong giá trị mẫu — một lần `git add .` là commit lộ PII khách. Và bảng pattern được CHÉP từ luật chứ không đọc Markdown trực tiếp, nên spec phải so hai bên: một bộ quét phụ thuộc cách người ta kẻ bảng sẽ chết lặng lẽ lúc ai đó đổi dấu gạch.',
  src:'scripts/qa/cleanup_check.js', rel:['g-rule_coverage','r-security'] },
{ id:'g-judge', t:'judge', cat:'gate',
  def:'TẦNG CHẤM cho phần máy không đo được. Máy KHÔNG chấm — nó chọn mẫu, giữ thang, kiểm lời chấm có neo, và đo người chấm còn hiệu chuẩn không.',
  detail:'Thang chấm 5 mục, mỗi mục kèm lý do nó không có máy, nhìn vào đâu, và bằng chứng nào phải nêu. Mẫu lấy TẤT ĐỊNH theo hạt giống từ (task, mẫu số, danh sách id), phân tầng theo phần trước dấu gạch chéo của cột Module.',
  why:'Bản đồ `rule:coverage` trả lời được "luật nào có máy". Phần còn lại không được để trống: một mục ghi "không đo được bằng máy" mà rồi không ai chấm thì nhãn đó chỉ là một lời miễn trừ.',
  cmd:'npm run judge -- --rubric   ·   --sample --task <K>   ·   --calib-form   ·   --calib-score <file>   ·   --check --task <K>',
  trap:'TỰ CHẤM LÀ VÔ NGHĨA. Người chấm trùng người viết nhãn thì tỉ lệ đúng chỉ đo khả năng nhớ nhãn mình vừa viết; máy so `cham_boi` với `_nhan_do_ai_viet`, đánh dấu `tu_cham` và cảnh báo ở MỌI lần `--check`. Mốc của v2.7.0 do một subagent chấm MÙ (20/20). Và bộ hiệu chuẩn tự khai giới hạn: nó chỉ gồm ca RÕ RÀNG nên chỉ bắt được lệch thang THÔ, không nói gì về ca biên — mà ca biên mới là chỗ phán đoán thật sự khó.',
  src:'scripts/qa/judge.js', rel:['g-rule_coverage','c-forcing-function','r-nocheat'] },
{ id:'g-canonical_drift', t:'canonical:drift', cat:'gate',
  def:'Đo ĐỘ TRÔI giữa Markdown canonical và bản xuất `.xlsx`, trên các cột NỘI DUNG.',
  detail:'So bằng cách parse CẢ HAI phía qua model canonical, không so chuỗi thô: exporter bóc Markdown nội dòng, bóc emoji và đổi <br> thành xuống dòng, nên so thô thì mọi ô đều khác và báo cáo thành vô dụng ngay lượt đầu. Chỉ so trường có cột ở cả hai phía, và KHAI RÕ trường nào không so được — "0 điểm trôi" mà không nói đã so mấy trường thì có thể nghĩa là so 0 trường.',
  why:'Từ v2.7.0, nội dung case lấy Markdown làm nguồn sự thật và Phase 2 execute ĐỌC Markdown vì rẻ token hơn (`.xlsx` nhị phân phải qua script in ra mới vào được ngữ cảnh). Chính luật đó mở một lỗ: QA sửa case trên Google Sheet là hợp lệ, lúc đó bản xuất đi trước và Markdown ở lại, mà execute vẫn đọc Markdown — lượt chạy dùng bộ CŨ và mọi verdict của nó nói về một bộ case không còn tồn tại.',
  cmd:'npm run canonical:drift   ·   npm run canonical:drift:enforce',
  trap:'HAI HƯỚNG TRÔI mang nghĩa ngược nhau. Markdown mới hơn chỉ là chưa xuất lại, execute vẫn đúng bộ. Bản xuất mới hơn mới là chỗ phải chặn. Máy suy hướng bằng mtime, mà mtime chỉ nói lần ghi cuối — một lượt checkout đặt lại cả hai phía — nên khi không kết luận được hướng thì nó cảnh báo chứ không chặn oan.',
  src:'scripts/qa/canonical_drift.js', rel:['c-canonical','g-result_ledger','c-forcing-function'] },
{ id:'g-result_ledger', t:'ledger:check', cat:'gate',
  def:'Chống MẤT KẾT QUẢ ÂM THẦM: đối soát cột Result trong bản xuất Excel với file `testcase-status*.json`.',
  detail:'Excel là bản người đọc, `testcase-status*.json` là bản máy ghi. Hai bên lệch nhau thì mọi con số độ phủ sau đó đều sai. Máy này so từng ô và chỉ ra ô nào mất.',
  why:'Ngày 08/10/2026, một task mất 129 ô kết quả trong Excel: cột Result của một cấp đã chạy đủ 184/184 tụt còn 47 ô. Dữ liệu gốc vẫn nguyên trong file status, nhưng KHÔNG máy nào biết Excel đã lệch khỏi chúng. Chuyện chỉ lộ vì chủ dự án tình cờ hỏi "test hết case chưa" — tức là nếu không ai hỏi, mọi báo cáo độ phủ sau đó đều sai mà vẫn trông bình thường.',
  cmd:'npm run ledger:check   ·   npm run ledger:check:enforce   ·   npm run ledger:snapshot',
  trap:'Excel xuất lại từ Markdown sẽ xoá trắng cột Result. Đối soát SAU mỗi lượt xuất lại, đừng tin bản vừa xuất.',
  src:'scripts/qa/result_ledger.js', rel:['c-canonical','g-output_gate','c-evidence'] },

{ id:'g-typecheck_task', t:'typecheck:task', cat:'gate',
  def:'Chạy `tsc --noEmit` trên automation CỦA MỘT TASK — vùng mà `npm run typecheck` chưa bao giờ soi.',
  detail:'`tsconfig.json` của kit khai `include: tests/**` và `exclude: outputs`, nên spec sinh ra dưới `outputs/<project>/tasks/<task>/automation/` nằm ngoài tầm nhìn của typecheck chung.',
  why:'Mọi câu "typecheck sạch" nói về spec của task đều RỖNG: công cụ không nhìn vào đó. Đo 09/10/2026 trên một task: hai thuộc tính KHÔNG TỒN TẠI được dùng ở 17 chỗ. `undefined !== true` luôn đúng, nên phép kiểm dựa vào chúng luôn xanh mà chẳng kiểm gì.',
  cmd:'npm run typecheck:task -- --task <TASK_KEY>',
  src:'scripts/qa/typecheck_task.js', rel:['g-gate_index','c-forcing-function','c-tin-hieu-sach-gia'] },

{ id:'g-tc_review', t:'tc:review', cat:'gate',
  def:'Chấm từng testcase theo rubric 8 tiêu chí, 0-2 điểm mỗi tiêu chí, rồi xếp loại theo tỉ lệ.',
  detail:'Sáu tiêu chí máy chấm đủ (rõ ràng · Expected đo được · độc lập · data cụ thể · truy vết · kỹ thuật). Hai tiêu chí máy chỉ chấm một phần và gắn cờ AI: đúng trọng tâm, và Actor/Context. Báo cáo ra reports/tc-review.md kèm trích nguyên văn chỗ chưa đạt và danh sách TC trùng.',
  why:'Kit đã chặn được từng lỗi rời, nhưng không chỗ nào trả lời câu người review hỏi đầu tiên: "bộ này dùng được chưa". Thiếu câu đó thì chất lượng bộ TC là cảm nhận của người đọc gần nhất, mà cảm nhận không so được giữa hai lượt hay hai người. Đo trên một bộ 212 case thật: trung bình 96,3%, và lộ ra 46 case không có oracle-ref.',
  how:['npm run tc:review để chấm và xem báo cáo.','npm run tc:review:enforce khi muốn CHẶN ở dưới ngưỡng.'],
  cmd:'npm run tc:review   ·   npm run tc:review:enforce',
  trap:'Tiêu chí gắn cờ AI KHÔNG được tính là đạt chỉ vì máy không kêu. Cộng điểm cho thứ chưa ai nhìn là cách nhanh nhất biến máy chấm thành máy phát chứng chỉ. Bộ chưa dùng tag kỹ thuật thì tiêu chí 8 là n/a và mẫu số co lại còn 14, không phải cho 0 điểm — cho 0 là phạt bộ cũ vì một luật ra đời sau nó.',
  src:'scripts/qa/tc_review.js', rel:['g-design_gate','g-dimension_coverage','c-canonical','sk-tc_reviewer'] },

{ id:'g-scope_anchor', t:'scope:anchor', cat:'gate',
  def:'Neo MẪU SỐ của Phase 1: kiểm xuất xứ của con số mà mọi tỉ lệ coverage chia cho.',
  detail:'Bốn câu hỏi: mỗi quyết định thu hẹp phạm vi có lý do và người ký chưa · con số mẫu số có danh mục liệt kê từng mục kèm NGUỒN không · catalog expected lấy từ tài liệu hay lấy từ build · so lượt trước, số case đổi mà danh mục KHÔNG đổi thì lượt trước đã sinh thiếu.',
  why:'Phase 1 có ba con số quyết định "thế nào là đủ", và cả ba đều do CHÍNH AGENT viết ra, rồi gate lấy chính nó làm chuẩn để chấm. Triệu chứng người dùng thấy: Phase 1 sinh 50 case, QA đọc thấy thiếu, yêu cầu rà lại thì lượt sau ra nhiều hơn hẳn. Không phải lượt sau giỏi hơn — là lượt đầu KHÔNG CÓ GÌ NEO nên dừng ở chỗ nó thấy hợp lý.',
  how:['npm run scope:anchor:init để in khung scope_inventory.md rồi điền, mỗi mục kèm nguồn.','npm run scope:anchor:enforce trước khi tin bất kỳ con số coverage nào.'],
  cmd:'npm run scope:anchor:init   ·   npm run scope:anchor   ·   npm run scope:anchor:enforce',
  trap:'Máy này KHÔNG đếm hộ case và KHÔNG tự quyết phạm vi — đoán hộ thì sai một lần là mất uy tín. Thiếu neo thì con số vẫn in ra, nhưng mang nhãn "chưa neo", và chưa neo thì không được kết luận PASS.',
  src:'scripts/qa/scope_anchor.js', rel:['g-dimension_coverage','c-canonical','g-preflight_gate'] },
{ id:'g-gate_index', t:'gates:index', cat:'gate',
  def:'Sinh DANH MỤC GATE của kit từ chính source. Trả lời được "kit có bao nhiêu gate, mỗi cái CHẶN gì, gọi ở đâu".',
  detail:'Quét source rồi suy mức từ code: exit 1 là CHẶN · ghi artifact là SINH · chỉ in là BÁO CÁO. Bảng hiện tại: 164 máy — 119 CHẶN, 25 SINH, 20 BÁO CÁO. Bản --check chặn khi bảng lệch source.',
  why:'Kit có hơn 30 npm script dạng gate và gần 60 file trong scripts/qa/, nhưng không chỗ nào trả lời được câu trên. Hệ quả không phải bất tiện: luận đề của kit là "luật cần MÁY", mà máy không LIỆT KÊ ĐƯỢC thì không kiểm toán được. Không ai biết một gate đã âm thầm tụt thành cảnh báo, hay đã mất nơi gọi.',
  how:['npm run gates:index để sinh lại bảng.','npm run gates:index:check để chặn khi bảng lệch source.'],
  cmd:'npm run gates:index   ·   npm run gates:index:check',
  ex:'SINH và BÁO CÁO KHÔNG phải gate bị nới, chúng không kiểm vi phạm. bugs:checklist chỉ in brief bug lịch sử, còn việc CHẶN nằm ở dim:coverage chiều §20.',
  trap:'Bốn "phát hiện" đầu tiên khi mới dựng bảng đều là lỗi của BẢNG, không của kit, nên phải hiệu chuẩn danh mục trước khi tin số nó đưa ra.',
  src:'scripts/qa/gate_index.js', rel:['c-forcing-function','c-gate-real-content','g-policy_source_check','f-gate-catalog'] },

{ id:'g-extension_integrity_check', t:'extension:check', cat:'gate',
  def:'Năm adapter Kit A phải nằm NGOÀI cây skill canonical, và 28 skill + 28 shim của kit không được đổi.',
  detail:'Kiểm từng adapter: đúng đường dẫn trong .agent/extensions/kit-a/adapters/, có chuỗi thẩm quyền (RULE_GLOBAL + canonical + "does not grant permission to skip gates"), trỏ tới SOURCE_GUIDE, và băm source guide khớp manifest. Chặn cả chiều ngược: adapter RÒ vào .agent/skills hay .claude/skills, hoặc INDEX.md nhắc tên extension.',
  why:'Đặt adapter trong .agent/skills làm 7 ca infra của kit đỏ (skills-shim, skills-route, /start) vì chúng không được đăng ký trong INDEX.md và shim. V9.1 dời ra ngoài để sửa tận gốc; cửa này giữ cho nó không quay lại.',
  how:['npm run extension:check'],
  src:'scripts/qa/extension_integrity_check.js', rel:['g-skills_index','c-forcing-function'] },

{ id:'g-bug_outcome', t:'bug:outcome', cat:'gate',
  def:'SỔ KẾT CỤC của claim bug, gộp MỌI task — và lời khai thẳng về bốn tỉ lệ: cái nào tính được, cái nào không và vì sao.',
  detail:'Tách HAI câu hỏi khác nhau: ① kit TỰ BẮT bao nhiêu claim sai trước khi nói thành lời (từ status withdrawn + phép kiểm nào bắt được) · ② BÊN NGOÀI phán thế nào (từ nhãn ket_cuc: accepted · rejected · by_design · duplicate · cannot_verify). Ghi nhãn bằng --ghi, bắt buộc --nguon, và nhãn NGƯỢC với claim thì bắt buộc --vi-sao. --enforce chặn khi claim đã log quá 14 ngày mà chưa có nhãn. Ghi tích luỹ vào knowledge/metrics/bug-outcomes.json.',
  why:'Chủ dự án nêu kit chưa có tỉ lệ false PASS / false bug / missed bug / inconclusive. Đo 09/11/2026 trên dữ liệu thật: 141 claim · 119 đã log · 0/119 có nhãn · 113 quá 14 ngày. Vấn đề không phải thiếu công cụ tính mà là SỔ BỎ RƠI LỚP ÂM — không ai tính được tỉ lệ sai từ một cuốn sổ chỉ chép phần đúng. Luật lớn nhất của máy: KHÔNG BAO GIỜ in một tỉ lệ mà không in mẫu số của nó; "8% trên 2 claim có nhãn trong 40 đã log" không phải tỉ lệ của dự án. Và nó nói thẳng false PASS + missed bug KHÔNG tính được từ sổ claim, kèm nguồn thay thế.',
  how:['npm run bug:outcome','npm run bug:outcome:ghi -- TC_001 --nhan rejected --nguon "DEV A" --vi-sao "đúng thiết kế theo FSD 4.2"','npm run bug:outcome:enforce'],
  src:'scripts/qa/bug_outcome.js', rel:['g-bug_claim','g-env_assumptions'] },

{ id:'g-env_assumptions', t:'lint:env', cat:'gate',
  def:'Bắt KHẲNG ĐỊNH PHỤ THUỘC MÔI TRƯỜNG: phép kiểm xanh ở nơi nó chạy và đỏ ở nơi nó không chạy.',
  detail:'Ba luật quyết được: ① biến môi trường đúng chữ hoa trên một BẢN SAO env (process.env tra không phân biệt hoa thường, {...process.env} thì CÓ) · ② truyền THƯ MỤC cho node --test (Node 22 coi positional là FILE; .nvmrc ghim 22) · ③ băm BYTE THÔ file văn bản mà không chuẩn hoá xuống dòng. Bỏ chú thích VÀ bỏ nội dung chuỗi trước khi khớp, nếu không nó bắt chính fixture trong spec gác nó. Lối thoát env-ok: phải KÈM LÝ DO >= 5 ký tự.',
  why:'Bốn sự cố trong MỘT phiên 09/11/2026, không cái nào là thiếu kiến thức. Cửa KHÔNG chặn thêm ai — nó làm câu "xanh nghĩa là đúng" trở thành ĐÚNG. Nghiệm thu bằng cách dựng lại bản TRƯỚC KHI VÁ của từng sự cố bằng git show rồi thả cửa vào: 3/3 bị bắt, đúng dòng, đúng lý do. Luật ④ (spec hạ tầng đọc file không đi theo gói) KHÔNG quyết được bằng lint — lượt thử cho 3/3 dương tính giả — nên cửa khai thẳng KHÔNG PHÁN ĐƯỢC và trỏ sang release:verify.',
  how:['npm run lint:env','node scripts/qa/env_assumptions.js --goc <cây khác>'],
  src:'scripts/qa/env_assumptions.js', rel:['g-gate_index','g-version_check'] },

{ id:'g-extension_router', t:'extension:route', cat:'gate',
  def:'Định tuyến TƯ VẤN, tất định, từ câu yêu cầu sang một trong năm adapter Kit A. Không bao giờ cho phép thực thi.',
  detail:'Khớp mẫu tiếng Việt lẫn tiếng Anh, trả về chủ sở hữu phía kit, các tiền điều kiện CÒN THIẾU và các cửa bắt buộc. execution_authorized luôn false, verdict luôn NOT_EXECUTED. Câu rỗng thì NÉM. Cờ ngữ cảnh là lời khai của người chạy, router KHÔNG tự xác minh.',
  why:'Năm adapter nằm ngoài cây skill canonical nên harness không quảng bá chúng; router là đường duy nhất tìm ra adapter_path. Nhưng nó là bộ khớp từ khoá, KHÔNG phải bộ phân loại ngữ nghĩa.',
  how:['npm run extension:route -- "FULL RBT"','npm run extension:route -- "manual execution" --context ctx.json'],
  src:'scripts/qa/extension_router.js', rel:['g-extension_integrity_check','g-skills_route'] },

{ id:'g-extension_benchmark', t:'extension:benchmark', cat:'gate',
  def:'Benchmark định tuyến TẤT ĐỊNH, 7 ca viết tay — KHÔNG phải benchmark chất lượng AI.',
  detail:'Năm ca phải khớp đúng adapter, hai ca ngoài miền (database migration, financial forecasting) phải KHÔNG khớp gì. In JSON kèm mục limitations tự khai: fixture nhỏ viết tay, không phải benchmark ngữ nghĩa, không chạy browser hay LLM.',
  why:'Một router không có ca ÂM thì chỉ cần khớp mọi thứ là đạt. Hai ca ngoài miền chính là phần làm phép đo phân biệt được.',
  how:['npm run extension:benchmark'],
  src:'scripts/qa/extension_benchmark.js', rel:['g-extension_router'] },

{ id:'g-v4_baseline_integrity', t:'extension:baseline', cat:'gate',
  def:'Lõi kit có đổi so với MỐC nhập extension không — một lượt, KHÔNG phải mỗi commit.',
  detail:'Chuẩn hoá xuống dòng trước khi băm (cả CR lẻ), giữ nguyên byte cho nhị phân, và chấp nhận khớp ở MỘT TRONG HAI dạng vì mốc nhập về tự trộn hai quy ước. Cờ --chot ghi lại mốc từ cây hiện tại; --raw giữ cách băm nguyên byte để so với chính file zip.',
  why:'Bản nhập về băm nguyên byte nên trên checkout Windows nó báo 264/931 và exit 1 trong khi nội dung thật là 931/931 — đo lại 667 file "khác" thì 667/667 chỉ khác xuống dòng. Cái cửa sinh ra để chứng minh "lõi không đổi" lại báo 72% lõi đã đổi. CỐ Ý không nối vào static-check: mốc là ảnh chụp đông cứng nên mọi thay đổi lõi chính đáng cũng làm nó đỏ, và vai trò đó đã có version:check.',
  how:['npm run extension:baseline','npm run extension:baseline -- --chot'],
  src:'scripts/qa/v4_baseline_integrity.js', rel:['g-version_check','c-forcing-function'] },

{ id:'g-v4_verify', t:'extension:verify', cat:'gate',
  def:'Chạy gộp ba cửa extension và gộp mã thoát.',
  detail:'Gọi lần lượt baseline integrity, extension integrity và routing benchmark; in PASS/FAIL từng cái kèm phần đuôi stdout, thoát 1 nếu có cái nào đỏ.',
  why:'Một lệnh để chạy cả cụm lúc nhập hoặc lúc nghi ngờ, thay vì nhớ ba lệnh rời.',
  how:['npm run extension:verify'],
  src:'scripts/qa/v4_verify.js', rel:['g-v4_baseline_integrity','g-extension_integrity_check','g-extension_benchmark'] },

{ id:'g-quickstart_numbers', t:'quickstart:numbers', cat:'gate',
  def:'Sinh bảng số đo trong QUICKSTART.md (số file track · số spec ci:scope đếm) thay vì giữ nó bằng tay.',
  detail:'Hai nguồn, không khai lại: số file từ git ls-files, số spec đọc từ STDOUT của ci_scope_check.js — đúng hai nguồn mà release-pipeline.spec.ts dùng để chấm. Cột GitLab trừ đúng số mục trong gitlab_strip.json. Thiếu .git (gói đã giải nén) hay thiếu gitlab_strip.json (lớp PROJECT) thì THOÁT 2, không kết luận "khớp".',
  why:'Bảng đó là số DẪN XUẤT nhưng từng chép tay, nên nó trôi BA lần trong một đợt phát hành: 919→920 khi thêm docs/rationale/start-pham-vi.md, 920→928 khi thêm fixture practice, 928→929 khi thêm báo cáo v2.10.2. Lần nào cũng chỉ lộ ra sau 10 phút chạy cả bộ. GATES.md, RULE_COVERAGE.md và trang này đều đã có máy sinh — bảng đó là chỗ cuối cùng còn trôi được.',
  how:[
    'npm run quickstart:numbers — sinh lại rồi commit.',
    'npm run quickstart:numbers:check — CI chạy cái này; lệch thì exit 1 kèm cả hai con số.',
  ],
  src:'scripts/qa/quickstart_numbers.js', rel:['c-forcing-function','g-gate_index','g-ci_scope_check'] },

{ id:'g-skills_practice', t:'skills:practice', cat:'gate',
  def:'Đọc MỘT skill xong có làm ra được sản phẩm qua được gate không. Chạy model thật, KHÔNG vào CI.',
  detail:'Mỗi bài chạy một phiên claude -p trong thư mục chỉ có ĐÚNG MỘT skill; cố ý KHÔNG chép prompt_templates/ nên model không mở được prompt phase để lấy thêm hướng dẫn. Làm được là nhờ skill, không nhờ thứ khác. Mỗi bài 3 lượt, đạt khi ít nhất 2/3. Lượt KHÔNG CHẠY ĐƯỢC bị loại khỏi mẫu số, không tính là trượt. Cờ --gia chạy một lượt và chỉ in chi phí; --luu lưu câu trả lời thô.',
  why:'skills:lint chấm mô tả có ĐỦ THÔNG TIN ĐỂ CHỌN, skills:template:check chấm mẫu có THẬT và có QUA MÁY. Cả hai đo TÀI LIỆU. Không cửa nào trả lời câu cuối: đọc skill xong có làm ra được sản phẩm không. Đây là chỗ kit B vượt gói nguồn — gói đó không có phép đo này.',
  how:[
    'npm run skills:practice:gia để đo chi phí MỘT lượt trước khi quyết chạy cả bộ.',
    'npm run skills:practice -- --bai <mã> --lan 3 --ra docs/<phiên bản>/PRACTICE.md',
    'Chạy tay trước mỗi bản phát hành. Kết quả ghi kèm NGÀY và PHIÊN BẢN MODEL.'
  ],
  cmd:'npm run skills:practice:gia   ·   npm run skills:practice -- --lan 3',
  ex:'Giá đo 06/11/2026: một lượt 65–114 giây, $0,30–0,45. Một bài 3 lượt $1,14. Cả 5 bài 15 lượt khoảng $5,7.',
  trap:'MỘT LƯỢT LÀ TUNG ĐỒNG XU. Hai lượt hiệu chuẩn CÙNG bài, CÙNG bộ chấm, CÙNG skill cho 2/5 rồi 5/5. Nếu dừng ở lượt đầu, kết luận sẽ là "automation_reviewer dạy không đủ" và việc tiếp theo là đi sửa một skill KHÔNG hỏng; ba lượt chính thức sau đó đều 5/5. Đó là vì sao ngưỡng 2/3 không phải thận trọng dư. Và đáp án bài 2 bản đầu tôi đếm số dòng BẰNG MẮT, sai cả 5 mục — để vậy thì bài tập chấm model "sai dòng" trong khi model nêu đúng; nay có ca spec đối chiếu từng dòng với đoạn mã thật.',
  src:'scripts/qa/skills_practice.js', rel:['g-skills_template','g-skills_route_live','c-forcing-function'] },

{ id:'g-skills_template', t:'skills:template:check', cat:'gate',
  def:'Skill khai output thì phải có MẪU, và mẫu phải tự qua máy kiểm của chính nó.',
  detail:'Quét mục `## Outputs` của mọi skill, đối chiếu với các dòng `Mẫu: <đường dẫn>`. Mẫu phải TỒN TẠI; frontmatter của mẫu khai `kiem_bang: <lệnh>` thì cửa nối đường dẫn mẫu vào cuối lệnh rồi CHẠY, exit khác 0 là CHẶN. Không có máy kiểm được thì BẮT BUỘC khai `vi_sao` — phần lớn cửa của kit đọc THƯ MỤC output của một task chứ không đọc file rời, nên "chưa có máy kiểm" là trạng thái thật và phải khai được.',
  why:'Khoảng cách của tiêu chí "hướng dẫn cụ thể" không nằm ở chỗ skill thiếu chữ, mà ở chỗ đọc xong vẫn chưa biết SẢN PHẨM trông thế nào. Đo 06/11/2026: trong 28 skill thì có 18 cái khai mục Outputs, tổng 47 output, và chỉ 1 output có mẫu. Mẫu KHÔNG phải khung trống — khung trống thì ai cũng dựng được và không ai học được gì từ nó; mẫu là bản ĐÃ ĐIỀN trên miền thật.',
  how:[
    'npm run skills:template:check để xem sổ nợ; bản :enforce mới chặn.',
    'Hạ nợ: viết thêm một mẫu, trỏ `Mẫu:` từ skill tới nó, rồi sửa `no.thieuMau` đúng số cửa in ra.',
    'Ngưỡng ở .agent/config/skills_template.json — một nguồn duy nhất, cùng khuôn skills_lint.json.'
  ],
  cmd:'npm run skills:template:check   ·   npm run skills:template:check:enforce',
  ex:'Mẫu đầu tiên tự qua máy thật: checklist Smoke hồ sơ lớp học, kiểm bằng `design_gate --mode checklist --file`, 0 chặn 0 cảnh báo. Chính máy đó chỉ ra mẫu còn thiếu bảng ký nhận.',
  trap:'SỔ NỢ chứ không chặn tất: chặn thẳng 47 output là đặt một ngưỡng đỏ ngay hôm đặt, và ngưỡng đỏ ngay hôm đặt là tiếng ồn, tiếng ồn thì bị tắt. Nợ PHÌNH chặn, nợ TRẢ RỒI MÀ KHÔNG HẠ SỔ cũng chặn — chỉ chặn một chiều thì sổ ở mãi con số cũ và mất nghĩa. Khoá nợ đặt NGOÀI `no` chặn ngay: lớp lỗi đó đã sống 13 ngày ở skills_lint.json. Và regex đọc `Mẫu:` sai HAI chiều trong một buổi: neo đầu dòng thì trượt ô bảng rồi báo nợ phình oan; nới ra thì bắt cả "Câu kích hoạt mẫu:" ở 18 skill và CHE nợ thật từ 46 xuống 29.',
  src:'scripts/qa/skills_template_check.js', rel:['g-skills_lint','c-forcing-function','g-design_gate'] },

{ id:'g-skills_route_live', t:'skills:route:live', cat:'gate',
  def:'Đo định tuyến skill bằng CHÍNH MODEL, không bằng đếm từ. Không vào CI vì mỗi lượt là một phiên model thật.',
  detail:'Mỗi câu trong tests/fixtures/skills_route.json chạy một phiên claude -p, công cụ làm việc bị CHẶN để model không đi dò thay vì định tuyến. Skill được chọn đọc từ lời GỌI công cụ Skill, KHÔNG từ lời model tự thuật. Cờ --trong-repo chạy ở gốc repo (hook CÓ chạy) để tách ảnh hưởng của ngữ cảnh; --gioi-han lấy mẫu và tự dán nhãn "đây là MẪU".',
  why:'skills:route:check chấm bằng TỪ NGỮ và tự khai giới hạn đó. Giới hạn ấy không phải lý thuyết: câu "soak test nửa tiếng" bị bộ chấm từ ngữ xếp dưới sàn 3,57 điểm, còn model thật gọi thẳng load_check ngay lượt đầu. Chỉ có thước đại diện thì người ta sẽ đi nhồi từ khoá vào description cho vừa một bag-of-words — làm mô tả tệ đi cho model thật để một con số đẹp lên.',
  how:[
    'npm run skills:route:live để quét bộ đầy đủ; thêm --trong-repo để đo kèm hook.',
    '--ra docs/<phiên bản>/ROUTE_LIVE.md ghi báo cáo kèm NGÀY và PHIÊN BẢN MODEL.',
    'Chạy tay trước mỗi bản phát hành, KHÔNG đưa vào CI.'
  ],
  cmd:'npm run skills:route:live   ·   node scripts/qa/skills_route_live.js --trong-repo',
  ex:'Điều nó dạy được, đo tuần tự 05/11/2026: rút 12 description từ ~250 xuống ~140 ký tự (-2,05 KB phần luôn nạp) KHÔNG làm định tuyến tụt đo được — trước 68,6–70,0%, sau 64,7–73,5%, hai dải chồng lên nhau, trung bình chênh 0,2 điểm. Trước đó một lượt 3 luồng đã cho 50 → 32,9% và suýt khiến nhát cắt bị hoàn tác; con số ấy là nhiễu do chạy song song.',
  trap:'BA lỗi đường ống cùng cho một triệu chứng "model không gọi skill nào", và không cái nào là lỗi định tuyến: spawn với shell:true nối tham số KHÔNG escape nên câu tiếng Việt vỡ; --allowed-tools KHÔNG giới hạn gì (phải dùng --disallowed-tools); stdin không chặn thì chờ 3 giây mỗi lượt. Lượt đầu ra 0/6 vì lỗi một. Và ĐỪNG so con số của --gioi-han với con số bộ đầy đủ: tôi đã so 20 câu với 90 câu rồi kết luận nhân quả, đối chứng cùng mẫu bác ngay.',
  src:'scripts/qa/skills_route_live.js', rel:['g-skills_route','c-forcing-function','g-skills_lint'] },

{ id:'g-token_session', t:'token:session', cat:'gate',
  def:'Đo phần LUÔN NẠP — thứ mọi phiên đều trả, kể cả phiên chỉ hỏi một câu.',
  detail:'Ba khối: CLAUDE.md · đầu ra hook SessionStart · frontmatter description của MỌI skill, command, agent mà harness quảng bá. Ngưỡng ở prompt_budget.json khoá alwaysOnMaxKB. Bản --phase <luồng> đo khối bắt buộc của một luồng (diem_vao + bat_buoc trong load_map.json, KHÔNG tính co_dieu_kien), ngưỡng ở phaseMaxKB.',
  why:'Khối thứ ba không nằm trong load_map.json nên prompt:budget không thấy nó — mà đo 04/11/2026 nó là khối LỚN NHẤT: 10,05 trên 16,29 KB, riêng 28 skill chiếm 7,28 KB. Tức trước cửa này, một dòng description dài thêm một câu làm MỌI phiên về sau đắt thêm, mãi mãi, và không gate nào kêu.',
  how:[
    'npm run token:session để đo phần luôn nạp.',
    'npm run token:phase1 để đo khối bắt buộc của Phase 1.',
    'node scripts/qa/token_session.js --moc in số đo hiện tại để chốt ngưỡng, thay vì đặt số bằng cảm giác.'
  ],
  cmd:'npm run token:session   ·   npm run token:phase1',
  ex:'KHÁC prompt:budget: máy đó đo chi phí CHẠY MỘT PHASE theo token; máy này đo chi phí MỞ MỘT PHIÊN theo KB. Hai cửa giữ CÙNG hệ số 3,2 ký tự/token để số của chúng so được với nhau, và có một ca test khoá điều đó.',
  trap:'Regex đọc description bản đầu dùng cờ /m, nên $ khớp cuối MỖI DÒNG và mô tả trải nhiều dòng bị đếm hụt — cửa báo RẺ hơn thực tế, tức sai về phía nguy hiểm. Ca đối chứng bắt được. Và thiếu `.claude/` (như cây-gói phát hành) thì cửa trả exit 2 KHÔNG PHÁN ĐƯỢC chứ không trả 0: cửa ⑩ của version_check.js từng trả "đạt" trong hoàn cảnh y hệt và làm release:verify đọc thành 13/15.',
  src:'scripts/qa/token_session.js', rel:['g-prompt_budget','c-forcing-function','g-library_drift'] },

{ id:'g-env_scope', t:'env:scope', cat:'gate',
  def:'Chặn "profile không ghim nổi cấp học nó đang đo", và gọi tên bí mật mà không đường nào đọc tới.',
  detail:'Hai mệnh đề. ① Mỗi profiles/<TASK>/task.env phải ghim QEMIS_CAP_HOC (CHẶN) và nên ghim QEMIS_NAM_HOC (cảnh báo). ② Khoá trong .env mang hậu tố không khớp khuôn <TIEN_TO>_<HAU_TO> mà uatDbClient.ts đọc, ví dụ LIB_MASTER_DB_RO_USERNAME_ADMIN, là bí mật chết: không đường nào chạm tới nó. Cửa chỉ in TÊN khoá, không bao giờ in giá trị. Chế độ --soi in khoá neo của từng profile để ĐO trước khi chốt luật.',
  why:'opsLogin.ts:419 — thiếu QEMIS_CAP_HOC thì app giữ mặc định "Mầm non", và nó chỉ console.warn. Lượt chạy KHÔNG gãy: đăng nhập được, đi hết bước, chụp đủ ảnh, chấm PASS trên cấp học không phải cấp mà case nói tới. Không ca nào đỏ. Đo 03/11/2026: profiles/CSDL-4039 là EMIS THCS mà không ghim khoá này.',
  how:[
    'npm run env:scope để soi cả bộ profile trên máy.',
    'node scripts/qa/env_scope_check.js --soi để ĐO trước, chốt luật sau.',
    'Chặn thật nằm ở preflight_gate.js --mode phase2 (hàm kiemGhimCapHoc), vì env:scope quét cả repo nên không vào CI được.'
  ],
  cmd:'npm run env:scope   ·   node scripts/qa/env_scope_check.js --soi',
  ex:'QEMIS_CAP_HOC= để RỖNG vẫn tính là chưa ghim: isReal() của opsLogin loại ô rỗng, nên "có tên khoá" KHÔNG phải "đã ghim".',
  trap:'Bản luật ĐẦU của cửa này bắt mỗi profile tự khai OPS_USERNAME, và nó TỐ OAN 7 trong 8 profile. Khi một cửa mới tố gần hết hiện trạng, giả thuyết đầu tiên phải là CỬA SAI. Đo lại thì cả 8 profile đều ghim đơn vị, và một tài khoản QEMIS đổi được Sở/cấp/trường qua /Manage/ChonTruong.aspx — nên .env giữ MỘT tài khoản app là đúng thiết kế. Cửa tố oan gần hết hiện trạng tệ hơn không có cửa, vì người ta sẽ tắt nó. Cửa cũng cố ý KHÔNG require runtime_config.js: file đó gọi loadEnvFiles() lúc nạp module, tức kéo cả .env thật vào tiến trình của chính cửa.',
  src:'scripts/qa/env_scope_check.js', rel:['g-preflight_gate','c-forcing-function','g-secret_scan'] },

{ id:'g-library_drift', t:'library:drift', cat:'gate',
  def:'Chặn "thư viện thuật ngữ đã trôi khỏi repo", đối chiếu chính trang này với source.',
  detail:'Kiểm những mệnh đề ĐỐI CHIẾU ĐƯỢC: toàn vẹn nội bộ (id trùng, rel gãy, thiếu trường) · mọi đường dẫn src có tồn tại · mọi npm run được nhắc có thật · mọi máy trong scripts/qa có mặt (hoặc miễn trừ kèm lý do) · số skill, số chiều coverage, số cột canonical, danh sách verdict status và tầng lỗi, ngưỡng rerun, slash command, phiên bản kit · bản build mới hơn nguồn và không gọi host ngoài.',
  why:'Trang là lớp DẪN XUẤT: nội dung viết tay, nguồn thì đổi liên tục. Ba lượt cập nhật gần nhất, lần nào cũng tìm ra fact đã cũ mà không có tín hiệu nào báo. Công cụ test-management cũ vẫn được dạy như đường chính, số cột canonical ghi thừa, số chiều coverage ghi thiếu, bảng skill sót mục mới nhất, và hai chỗ rơi dấu nháy làm trang trắng trong khi build vẫn báo OK. Tức trang chỉ đúng vào lúc có người NHỚ RA phải cập nhật.',
  how:[
    'Miễn trừ khai ở .agent/config/library-drift.allow.json và BẮT BUỘC ghi lý do.',
    'Khối lạ trong allowlist bị chặn, và miễn trừ trỏ tới thứ không còn tồn tại cũng bị chặn.',
    'Không kiểm nội dung văn xuôi đúng hay sai, máy không đọc được ý nghĩa.'
  ],
  cmd:'npm run library:build   ·   npm run library:drift',
  ex:'Lượt chạy đầu tiên trả về 4 chỗ trôi: một lệnh không tồn tại, ba verdict status mới chưa có mặt, và một cái là lỗi của CHÍNH GATE — regex đếm cột bắt trúng "0 cột" trong bảng lỗi thường gặp.',
  trap:'Gate so theo VĂN BẢN, nên viết lại một con số cũ để kể lịch sử cũng bị bắt (đã xảy ra với đúng mục này). Diễn đạt tránh con số thay vì nới luật, cùng cách xử lý như luật một-công-cụ. Và nhớ: nguồn quyết luôn là repo, sửa trang cho khớp chứ đừng sửa ngược.',
  src:'scripts/qa/library_drift.js', rel:['c-canonical','g-gate_index','c-forcing-function','c-gate-real-content','g-skills_index'] },

{ id:'g-course_numbers', t:'course:numbers', cat:'gate',
  def:'CHẠY sản phẩm thực hành rồi so ví dụ trong bài giảng với thứ nó trả về thật.',
  detail:'Khởi động app thực hành ở một cổng riêng rồi đo bốn thứ: các ca canonical có khớp bảng khai trong gate không · CẢ BA bug cài sẵn còn sống không · mọi đường API bài giảng có gọi thì app có thật không · và bài giảng còn sót dấu vết nghiệp vụ CŨ không. Một ca được khai là bug-phải-lộ thì app BẮT BUỘC khác spec: sản phẩm thực hành mà bug không lộ ra thì cả tài liệu mất phép đối chứng.',
  why:'Ví dụ trụ cột của tài liệu nằm ở Bài 1 và nó KHÔNG chạy được. Trả giá hai lượt. Lượt một: giá trong app khác giá trong bài, tên trường API khác, bộ dữ liệu của bài không dựng được từ bảng giá, và nặng nhất là bug cài sẵn không hề lộ ra với dữ liệu bài dùng. Lượt hai, lúc đổi nghiệp vụ: giao diện app gửi customerId/qty trong khi server đọc hocVienId/soSuat, tức là màn hình đã ngừng chạy từ trước đó, và bài factory thì dạy một API mà app KHÔNG có. Không gate nào bắt được vì mọi phép kiểm cũ đọc VĂN BẢN.',
  how:['npm run course:numbers trước khi sửa bất cứ con số nào trong bài giảng.','Đổi app thì đổi bảng canonical trong gate, và ngược lại.'],
  cmd:'npm run course:numbers',
  ex:'HV01 có hai lớp mới, Foundation bắt đầu 01/07 và Lớp chính bắt đầu 01/09. BR-02 nói mốc lấy theo lớp chính nên hạn mới phải là 31/08/2026, app lấy Foundation và trả 30/06/2026. HV03 chỉ có một lớp mới thì app trả đúng, và đó là ca phân biệt.',
  trap:'Bản đầu của gate xếp 8.750 vào danh sách số cũ và báo oan 3 chỗ, trong khi con số đó vẫn đúng. Danh sách dấu vết cũ phải khai tường minh, đừng đoán bằng regex tiền tệ. Nghiệm thu bằng 4 phép tiêm: vá từng bug một, và xoá một đường API, mỗi lần phải CHẶN.',
  src:'scripts/qa/course_numbers.js', rel:['c-gate-real-content','g-library_drift','g-course_maturity'] },

{ id:'g-course_maturity', t:'course:maturity', cat:'gate',
  def:'Sinh khối "Bộ kit của bạn đang ở đâu" cho từng bài giảng, từ chính giáo trình.',
  detail:'Khối này nhắc số bài, số cấp độ và tên bài kế tiếp. Toàn những thứ đã đổi ba lần trong một tuần. Viết tay thì nó trôi khỏi giáo trình mà không ai biết, nên nó là lớp DẪN XUẤT của docs/COURSE.md, y như trang thư viện.',
  why:'Đo trên 43 bài giảng: 43 bài không có chỗ nào trả lời hai câu mà người đọc từ số 0 hỏi ở khoảng bài thứ mười bảy. Tôi đang ở đâu, và cấp độ này còn mấy bài. Mất phương hướng giữa một tài liệu 65 giờ là lý do người ta bỏ dở, không phải vì nội dung khó.',
  how:['npm run course:maturity ghi khối vào từng bài.','npm run course:maturity:check chặn khi có bài lệch, dùng ở CI.'],
  cmd:'npm run course:maturity   ·   npm run course:maturity:check',
  ex:'Bài 2 hiện: CẤP ĐỘ 1 · AUTOMATE, bài 2/4 của cấp độ này, cả tài liệu bài 2/29, và câu nói được sau cấp độ đó.',
  trap:'Đừng sửa tay khối này. Lượt sinh sau ghi đè, và bản --check sẽ chặn vì nội dung lệch giáo trình.',
  src:'scripts/qa/course_maturity.js', rel:['c-canonical','g-library_drift'] },

{ id:'g-rule_lookup', t:'rule / rule:toc', cat:'gate',
  def:'Tra RULE_GLOBAL.md THEO MỤC, thay vì đọc cả file.',
  detail:'Đo 07/09/2026: RULE_GLOBAL.md có 465 dòng, 51.116 ký tự, khoảng 12.800 token, và đó là SÀN, vì 12% ký tự có dấu nên thực tế cao hơn.',
  why:'File này KHÔNG auto-load nên không ăn token mỗi phiên (thứ luôn-trong-ngữ-cảnh là CLAUDE.md, 13 dòng). Vấn đề nằm ở lúc CẦN tra: không có mục lục thì cách duy nhất là đọc cả file — 12,8k token cho một câu trả lời. Chính thước đo của kit (doc_budget) đặt ngưỡng đọc-thẳng ở 8.000, nên đọc cả file đã vượt 1,6 lần.',
  ex:'Tra riêng mục Security tốn 287 token, rẻ hơn 45 lần so với đọc cả file.',
  cmd:'npm run rule -- <tên mục>   ·   npm run rule:toc',
  src:'scripts/qa/rule_lookup.js', rel:['f-rule-global','g-doc_budget','c-canonical'] },

{ id:'g-version_check', t:'version:check', cat:'gate',
  def:'Chặn phát hành thiếu sót. Kit phải có số phiên bản, không phải ngày tháng.',
  detail:'Kiểm phiên bản khai trong package.json, và khi chạy từ tag thì kiểm khớp tag. Kit hiện ở 2.0.0.',
  why:'Kit được phát cho nhiều dự án và sửa rất thường xuyên. Không có version thì ba chuyện xảy ra: không biết dự án nào đang ở bản nào (có bản vá quan trọng cũng không có đường thông báo) · không có mốc để quay lui · và bản phát ra không trả lời được câu hỏi duy nhất người nhận cần. Nâng bản này có phải sửa gì trong lớp PROJECT không. Chỉ MAJOR/MINOR nói được điều đó. Ngày tháng thì không.',
  cmd:'npm run version:check',
  src:'scripts/qa/version_check.js', rel:['f-kit-version','g-package_kit','g-verify_release','f-changelog'] },

{ id:'g-package_kit', t:'package:kit', cat:'gate',
  def:'Đóng gói bản phát hành SẠCH của kit vào dist/ — chỉ lớp GENERIC.',
  detail:'Nguyên tắc duy nhất: gói chỉ chứa lớp GENERIC theo kit-layers.md. Lớp PROJECT không được lọt.',
  why:'Hai lý do khác nhau và đều nghiêm trọng. Một là SECRET và PII: .env*, profiles/<TASK>/task.env, knowledge/**, outputs/** đều là dữ liệu công ty. Hai là ORACLE SAI: file quy ước DB chứa schema và bản đồ cột↔nhãn ĐO TỪ DB CỦA MỘT dự án cụ thể. Phát cho dự án khác thì nó thành oracle sai, mà sai im lặng.',
  cmd:'npm run package:kit',
  trap:'Đây là lý do ranh giới GENERIC/PROJECT không phải chuyện gọn gàng mà là chuyện an toàn.',
  src:'scripts/qa/package_kit.js', rel:['f-kit-layers','r-security','g-verify_release','g-version_check'] },

{ id:'g-verify_release', t:'release:verify', cat:'gate',
  def:'Chứng minh bản phát hành chạy được từ con số 0, đúng trải nghiệm của người nhận kit.',
  detail:'Giải nén gói vào thư mục sạch rồi npm ci và chạy thử. Đây là thước đo chính của cả luồng phát hành, không phải bước tạo Release.',
  why:'Mọi gate khác chạy TRONG repo: có .git, có node_modules, có lớp PROJECT. Người nhận kit thì không có gì trong số đó. Khoảng cách ấy đã sinh lỗi thật. Hai gate từng crash vì gọi git ls-files vô điều kiện, và chỉ lộ ra khi giải nén vào thư mục sạch.',
  cmd:'npm run release:verify',
  ex:'Bài học đi kèm: gate nào dùng git phải chịu được trường hợp KHÔNG có .git. Ba gate nay dùng chung một helper thay vì vá lần thứ ba.',
  src:'scripts/qa/verify_release.js', rel:['g-package_kit','g-version_check','c-gate-real-content','f-kit-layers'] }
,

/* ── Máy thêm ở v2.5.0 và v2.6.0 ──────────────────────────────────────────
   Rà 11/10/2026: 6 máy của v2.5.0 có trong GATES.md mà CHƯA có mục ở đây.
   Thiếu mục nghĩa là người đọc tra không ra, và một máy tra không ra thì coi
   như không có — đúng lý do nhóm 2e ra đời hồi 29/09. */

{ id:'g-matrix_coverage', t:'matrix:coverage', cat:'gate',
  def:'Ma trận tổ hợp phải phủ theo LỚP KẾT QUẢ, không phủ theo số dòng.',
  detail:'Đọc khối "Lớp kết quả" khai trong tài liệu thiết kế rồi đối chiếu với bảng ma trận: lớp nào khai mà không dòng nào cho ra nó thì nêu tên. Không khai lớp nào thì gate nói "CHƯA ĐƯỢC GÁC", KHÔNG in ĐẠT.',
  why:'Pairwise phủ CẶP GIÁ TRỊ, và một bộ phủ đủ cặp vẫn có thể bỏ sót cả một lớp kết quả — ví dụ nhánh "từ chối vì quá hạn" không xuất hiện ở dòng nào. Đếm dòng thì thấy đủ; đếm lớp kết quả mới thấy thiếu.',
  how:['Khai lớp kết quả TRƯỚC khi dựng ma trận, không khai sau cho khớp.','Gate không tự suy lớp kết quả từ văn bản: suy bằng từ khoá đã sinh dương tính giả nhiều lần.'],
  cmd:'npm run matrix:coverage -- --task <KEY>',
  ex:'Bản đầu của chính gate này đọc khối khai bằng regex có `\\b` sau chữ có dấu, nên nó báo "không có khối khai" cho một file hoàn chỉnh.',
  trap:'Không khai lớp kết quả thì đừng đọc "không có cảnh báo" thành "đã phủ đủ".',
  src:'scripts/qa/matrix_coverage.js', rel:['c-oracle','g-dimension_coverage'] },

{ id:'g-run_analysis', t:'run:analysis', cat:'gate',
  def:'Lượt chạy này có đủ MẪU SỐ để kết luận chất lượng sản phẩm không.',
  detail:'Chia BLOCKED theo dải 5% và 20%, tách nợ test (SKIP vì thiếu môi trường) khỏi lỗi sản phẩm, và chỉ so xu hướng khi dấu vân tay bộ TC (sha256 của danh sách tcId đã sắp) KHỚP lượt trước.',
  why:'Một lượt chạy 300 case với 80 case BLOCKED không nói được gì về chất lượng, nhưng báo cáo của nó trông y hệt một lượt sạch. Và so xu hướng giữa hai bộ TC khác nhau là so hai thứ khác nhau.',
  how:['BLOCKED trên 20% thì kết luận chất lượng là BLOCKED, không phải FAIL hay PASS.','Dấu vân tay lệch thì KHÔNG vẽ xu hướng, nói rõ là bộ đã đổi.'],
  cmd:'npm run run:analysis -- --task <KEY>',
  ex:'Là bước 6 của `phase2:check`.',
  trap:'SKIP vì thiếu tài khoản là NỢ TEST, không phải sản phẩm tốt.',
  src:'scripts/qa/run_analysis.js', rel:['c-observation','g-dimension_coverage'] },

{ id:'g-release_summary', t:'release:summary', cat:'gate',
  def:'Khuyến nghị go/no-go có căn cứ, và KHÔNG tự quyết thay người.',
  detail:'Bảy tiêu chí, mỗi tiêu chí kèm cột `nguồn` trỏ tới artifact sinh ra nó. Từ chối chạy khi chưa có `exit_criteria.json`, và từ chối khi `mtime` của tiêu chí MỚI HƠN kết quả chạy — tiêu chí sửa sau khi đã biết kết quả thì nó không còn là tiêu chí.',
  why:'Một bản tóm tắt phát hành không có nguồn thì nó là ý kiến. Và `--enforce` KHÔNG BAO GIỜ chặn khi kết luận là NO-GO: quyết định phát hành là của người, máy chỉ đưa căn cứ.',
  how:['Khai `exit_criteria.json` TRƯỚC khi chạy bộ test.','Đọc cột `nguồn` trước khi tin một dòng.'],
  cmd:'npm run release:summary -- --task <KEY>   ·   npm run release:summary:init',
  ex:'Tiêu chí sửa sau kết quả thì gate từ chối chạy, kèm chênh lệch mtime.',
  trap:'`--enforce` không chặn NO-GO. Đừng đọc "exit 0" thành "được phát hành".',
  src:'scripts/qa/release_summary.js', rel:['c-observation','g-self_review'] },

{ id:'g-auto_review', t:'auto:review', cat:'gate',
  def:'Bảy luật cho automation VIẾT THEO TASK, thứ trước đây không máy nào soi.',
  detail:'Soi spec trong `outputs/**/automation/`: hard sleep, test không assert, locator theo spec, và bốn luật khác. Phần locator giao cho `lint:locator` chứ không viết lại. Nợ hard sleep khai theo SỐ LƯỢNG trong config: nhiều hơn là chặn, ít hơn là nhắc hạ con số.',
  why:'Kit có gate cho testcase và cho tài liệu, nhưng automation do agent viết trong `outputs/` thì không ai soi. Một test không có assertion vẫn xanh.',
  how:['Quét trên bản mã đã XOÁ RUỘT chuỗi và chú thích, để một fixture chứa `sleep(` không bị tính là vi phạm.','Hạ số nợ trong config khi trả được nợ, đừng nới nó.'],
  cmd:'npm run auto:review   ·   npm run auto:review:enforce',
  ex:'Luật `no-assert` dùng lookbehind để không bắt nhầm `requestTest(`.',
  trap:'Cây không có `.git` được coi là tầng CHẶN — đó đúng là bản kit đã đóng gói.',
  src:'scripts/qa/automation_review.js', rel:['g-locator_lint','c-gate-real-content'] },

{ id:'g-frontmatter_check', t:'frontmatter:check', cat:'gate',
  def:'File định nghĩa agent/skill phải THẬT SỰ NẠP ĐƯỢC: gác đúng những điều kiện mà tài liệu Claude Code nêu là làm một file bị BỎ QUA.',
  detail:'Kiểm bằng chữ, không dùng parser YAML: có frontmatter · có name và description · name khớp tên file/thư mục · giá trị chứa ": " phải bọc nháy. Chuẩn hoá CRLF bằng /\\r\\n/g chứ không /\\r/g — repo này dùng CRLF, và kit có cửa riêng bắt đúng lớp lỗi đó.',
  why:'.claude/agents/case-debugger.md nằm trong repo từ 10/10/2026 và CHƯA BAO GIỜ được harness đăng ký, quan sát ở BA phiên: Agent(case-debugger) trả về "Agent type not found". Tôi đoán sai suốt ba phiên là vì thiếu dòng model:, trong khi tài liệu nói model: là TUỲ CHỌN. Parse bằng parser thật thì ra ngay: dòng description chứa ": " không bọc nháy, và trong YAML đó là lỗi. Quét toàn bộ: 5/75 file vỡ cùng một kiểu. Sửa xong, agent đăng ký được NGAY TRONG CÙNG PHIÊN.',
  how:['npm run frontmatter:check để gác.','--dir <thư-mục> để soi một cây tạm, không phải sửa file repo.'],
  cmd:'npm run frontmatter:check',
  ex:'Hai skill vỡ YAML vẫn Skill(<tên>) gọi được, nên skill và agent KHÔNG cùng cách nạp: skill nhận theo thư mục, agent nhận theo name trong frontmatter.',
  trap:'Đây KHÔNG phải bộ parse YAML. Một frontmatter vỡ theo kiểu khác — thụt lề sai, list hỏng, neo/alias — thì cửa này KHÔNG thấy. Nó gác đúng lớp lỗi đã xảy ra, cộng vài lớp cùng họ.',
  src:'scripts/qa/frontmatter_check.js', rel:['g-skills_index','g-skills_lint','c-forcing-function'] },
{ id:'g-skills_lint', t:'skills:lint', cat:'gate',
  def:'Mô tả của một skill có đủ thông tin để CHỌN nó hay chưa.',
  detail:'Kiểm mô tả có nói "dùng khi nào" và "không dùng khi nào", và mọi đường dẫn trong skill phải tồn tại. Phần kiểm đường dẫn chỉ soi thư mục gốc của repo, KHÔNG soi `knowledge/**` (gitignore) hay đường dẫn tương đối theo task.',
  why:'28 skill không auto-load: agent phải tự chọn. Một mô tả không nói "khi nào" thì nó không giúp chọn, và skill đó coi như không tồn tại.',
  how:['Mô tả nêu điều kiện kích hoạt, không nêu tính năng.','Đường dẫn trong skill phải là đường dẫn thật.'],
  cmd:'npm run skills:lint   ·   npm run skills:lint -- --enforce',
  ex:'Bản đầu soi cả `knowledge/**` nên xanh ở máy local mà chặn 5 chỗ trên cây sạch.',
  trap:'Nợ mô tả khai theo số lượng: nhiều hơn là chặn, ít hơn là nhắc hạ con số.',
  src:'scripts/qa/skills_lint.js', rel:['f-kit-layers'] },

{ id:'g-knowledge_bootstrap', t:'knowledge:bootstrap', cat:'gate',
  def:'Dựng KHUNG `knowledge/domain` ở trạng thái `draft`, để kho không ở lại rỗng.',
  detail:'Sinh bản ghi `status: draft` từ bộ testcase canonical. `--apply` từ chối chạy nếu không có `--top <n>` hoặc `--module "<tên>"`: sinh hàng loạt không giới hạn là cách tạo ra một kho đầy khung rỗng.',
  why:'Trước v2.5.0 không có cách ghi một bản ghi "chưa ai xác nhận": `confirmed_by` bắt buộc và `status` không nhận `draft`. Dự án mới có `knowledge/` rỗng thì nó ở lại rỗng, vì bước đầu tiên đã bị chặn.',
  how:['`draft` KHÔNG phải oracle: case trỏ vào một rule còn draft thì `domain:check` chặn.','Chốt rule bằng `confirmed_by` rồi mới đổi sang `active`.'],
  cmd:'npm run knowledge:bootstrap -- --module "<tên>" --apply',
  ex:'Lỗ này làm cả hạng mục bất khả thi trước đó, không phải chuyện thiếu tiện ích.',
  trap:'Khung draft nhiều mà không ai chốt thì kho vẫn rỗng về nghĩa.',
  src:'scripts/qa/knowledge_bootstrap.js', rel:['g-domain_rules','c-oracle'] },


{ id:'g-full_suite', t:'full:suite', cat:'gate',
  def:'Sổ ghi lượt chạy CẢ BỘ, và cửa chặn đóng gói khi sổ đã cũ so với cây hiện tại.',
  detail:'Sổ ghi `head` (SHA của HEAD), `van_tay` (băm nội dung mọi file mà package_kit sẽ gói), số xanh/đỏ/bỏ qua và TÊN từng test đỏ. `package:kit` đối chiếu cả SHA lẫn vân tay: lệch một trong hai là CHẶN. Không ghi sổ khi typecheck đỏ, và không ghi khi không đọc được con số nào từ output — một phép đo hỏng không được thành một con số.',
  why:'Một dòng chữ "phải chạy cả bộ trước khi đóng gói" không chặn được ai. Đã trả giá thật: người làm chỉ chạy các spec VỪA VIẾT rồi báo con số đó như con số của cả bộ, và 15 test đỏ ở chỗ khác đi lọt tới tận bước phát hành. Sổ ghi SHA của HEAD và vân tay nội dung gói; lệch một trong hai thì package:kit CHẶN. Không có cờ bỏ qua.',
  cmd:'npm run full:suite',
  trap:'Sổ nằm trong .gitignore — nó là biên bản MỘT lượt chạy trên MỘT máy, không phải tài sản của repo. CI phải tự chạy, không mượn sổ của ai.',
  ex:'Từ 14/10/2026 nó typecheck TRƯỚC: Playwright chạy .ts transpile-only nên không bắt lỗi kiểu, và 3 lỗi TS2339 từng đi qua trọn một lượt xanh rồi chỉ chết trong gói.',
  src:'scripts/qa/full_suite_ledger.js', rel:['g-package_kit','g-verify_release'] },

{ id:'g-authz_expand', t:'authz:expand', cat:'gate',
  def:'Trục ⑥: liệt kê biến thể PHÂN QUYỀN quanh mỗi case — dọc (vai trò thấp hơn) · ngang (IDOR) · ẩn≠cấm.',
  detail:'Ba nhóm biến thể: DỌC (vai trò thấp hơn — cần ≥2 tài khoản), NGANG/IDOR và ẨN≠CẤM (đo được bằng MỘT tài khoản, nếu luật có neo trong knowledge/domain). Trạng thái: pass · fail · unknown (chưa thử) · needs_account (thiếu tài khoản, xin được) · thieu_nang_luc (vai trò không tồn tại, đã xác nhận) · needs_config · chi_chay_tay (biến thể GHI, không tự chạy trên UAT). Chỉ pass/fail là bằng chứng.',
  why:'Máy này KHÔNG dò: phần dò đã có ở discovery/roles.js với ba mức bằng chứng. Nó trả lời một câu khác — case này còn thiếu biến thể phân quyền nào — và nó không gửi request nào, có test khoá theo hướng chuyện đó.',
  cmd:'npm run authz:expand -- --config requirements/authz_matrix.json',
  trap:'Luật phải khai NÓ NÓI VỀ VAI TRÒ NÀO. BR-NHANSU-029 nói về tài khoản trường; chạy nó bằng tài khoản admin thì "xem được đơn vị khác" rất có thể là ĐÚNG, và kết luận ngược lại là một bug bịa ra từ tiền đề đúng một nửa.',
  ex:'Trạng thái thieu_nang_luc (vai trò không tồn tại) chỉ dùng được khi khai đủ vi_sao · xac_nhan_boi · ngay — và nó KHÔNG bao giờ thành PASS.',
  src:'scripts/qa/authz_expand.js', rel:['c-oracle','g-security'] },

{ id:'g-oracle_calc', t:'oracle:calc', cat:'gate',
  def:'Trục ⑦: canh bộ oracle giá trị tính toán — oracle ma · rule draft · oracle đọc app · thiếu ca lệch.',
  detail:'Canh tĩnh trên nguồn ĐÃ BỎ CHÚ THÍCH — nếu không thì chính khối chú thích giải thích "không được dùng page" sẽ làm máy đỏ, và người ta gỡ lời giải thích cho xanh. Bốn luật: oracle_ref phải tra ra rule active · không chạm page/locator/expect/DOM · có cả ca dung lẫn ca lech · 0 oracle là CHƯA KIỂM chứ không phải đạt.',
  why:'Oracle tính kỳ vọng TỪ ĐẶC TẢ rồi spec so giá trị app với nó. Nhưng một hàm viết theo quan sát app rồi gắn một mã BR- vào vẫn trông hợp lệ và vẫn xanh mãi mãi — đó là app==app hạ xuống tầng thư viện, chỗ khó thấy hơn hẳn tầng testcase.',
  cmd:'npm run oracle:calc',
  trap:'Mỗi oracle bắt buộc có CẶP ĐỐI CHỨNG: một ca đúng và một ca LỆCH (giá trị app có thể trả, mà oracle phải khác). Ca lệch lấy từ examples của chính rule trong knowledge/domain, đừng tự nghĩ ra.',
  ex:'Kho rule RỖNG là CHƯA KIỂM (exit 2), không phải "mọi oracle đều là ma" — gói mang knowledge/domain rỗng, và bản đầu kết oracle thật là ma.',
  src:'scripts/qa/oracle_calc_check.js', rel:['c-oracle','g-domain_rules'] },

{ id:'g-concurrency_check', t:'concurrency:check', cat:'gate',
  def:'Đo TÍNH ĐÚNG ĐẮN khi nhiều lượt gọi cùng chạm một tài nguyên — không đo tốc độ.',
  detail:'Bắn N lượt gọi đã chuẩn bị sẵn bằng Promise.all rồi ĐO độ lệch thả thật. Lệch quá ngưỡng (mặc định 50ms) thì trả CHUA_KIEM chứ không phán: không thể bắn N request đúng cùng thời điểm, nên máy đo độ lệch thay vì giả vờ nó bằng 0. Trần N cứng là 10, config chỉ hạ xuống được. Ba nơi chạy: fixture · uat_doc (chỉ đọc lại kiểm bất biến) · uat_ghi (mặc định TỪ CHỐI).',
  why:'Lỗi tranh chấp không lộ ra ở một lượt chạy tuần tự. Duyệt hai lần, trừ kho xuống âm, callback xử lý trùng — tất cả chỉ xuất hiện khi hai lượt chen vào giữa khoảng đọc-rồi-ghi của nhau.',
  cmd:'npm run concurrency:check',
  trap:'Kịch bản không khai BẤT BIẾN ở trạng thái cuối thì ra CHUA_KIEM, không được tính là PASS vì "chạy không lỗi". Và HTTP 500 là FAIL, không phải "đã chặn có kiểm soát".',
  ex:'Đây KHÔNG phải load test. Muốn đo thông lượng thì dùng K6 ở tests/load/ — hai câu hỏi khác nhau.',
  src:'scripts/qa/concurrency_check.js', rel:['g-security','c-oracle'] },

{ id:'g-skills_refcheck', t:'skills:refcheck', cat:'gate',
  def:'Mọi link nội bộ trong skill phải trỏ file có thật — và phân biệt link THẬT với đường dẫn MINH HOẠ.',
  detail:'Ba dấu hiệu nhận ra đường dẫn minh hoạ: chứa placeholder dạng ngoặc nhọn · nằm trong khối mã · là ô bảng mô tả file đầu ra. Những dạng đó KHÔNG tính là link, nên không bị gắn cờ.',
  why:'Một bộ skill có link chết thì người đọc bấm vào không ra gì, và không có gì đỏ. Nhưng đếm ngây thơ còn tệ hơn: nó gắn cờ cả ví dụ, và cách sửa nhanh nhất là gỡ ví dụ khỏi tài liệu — tức làm tài liệu nghèo đi để chiều một cái máy đếm sai.',
  cmd:'npm run skills:refcheck',
  trap:'Luật "đứng sau chữ VD thì bỏ qua" đã bị BỎ: nó từng bỏ qua ba link tới một file CÓ THẬT. Một luật bỏ qua được link thật thì nó nuốt luôn link gãy thật.',
  ex:'Đối chứng hai chiều lấy từ bộ skill của một kit khác: ba dạng minh hoạ phải đi qua, một link thật gãy phải bị chặn.',
  src:'scripts/qa/skills_refcheck.js', rel:['g-skills_index'] },

{ id:'g-ambiguity_gate', t:'ambiguity:gate', cat:'gate',
  def:'Cổng mơ hồ có CODE đứng sau: chặn khi task đã sinh case trong lúc cổng còn `PENDING`.',
  detail:'Đọc `AMBIGUITY_GATE` trong `task.md` rồi so khớp CHÍNH XÁC với danh sách khai ở `ambiguity_states.json`. Ba trạng thái hợp lệ, mỗi cái một nghĩa vụ riêng: `RESOLVED` đòi mọi câu Critical/High có trả lời · `PARTIALLY RESOLVED` đòi mỗi câu còn mở nói rõ nó CHẶN GÌ · `RESOLVED-BY-DEFAULT` đòi người và ngày. Mặc định chạy chế độ DI TRÚ: chỉ chặn ca rõ ràng sai, trạng thái lạ thì cảnh báo.',
  why:'Trước v2.9.2, "DỪNG tới khi RESOLVED" là lời dặn trong workflow mà không script nào đọc rồi dừng — việc dừng phụ thuộc agent tự tuân thủ, và trạng thái do người tick. Sinh case khi cổng chưa mở nghĩa là viết kỳ vọng dựa trên phỏng đoán, và chạy lại không phát hiện ra: nó chỉ xác nhận cùng một kỳ vọng sai.',
  cmd:'npm run ambiguity:gate -- --task <TASK_KEY>',
  trap:'Hai trạng thái CHỨA chuỗi `RESOLVED`. Kiểm bằng `includes` thì chúng lọt qua im lặng; kiểm bằng so bằng thì chặn cả việc đang chạy hợp lệ. Phải khớp chính xác, và khớp DÀI NHẤT trước.',
  ex:'Đo trên 5 task thật trước khi bật: chế độ di trú 0 đỏ, chế độ chặt 2 đỏ — và 2 ca đó là vi phạm thật, không phải lỗi đọc.',
  src:'scripts/qa/ambiguity_gate.js', rel:['c-oracle','g-preflight_gate'] },

{ id:'g-case_paths', t:'case:paths', cat:'gate',
  def:'Đường import tương đối phải khớp tên file thật, ĐÚNG hoa-thường.',
  detail:'Đọc danh sách thư mục rồi so chuỗi chính xác, không hỏi hệ điều hành — nên kết luận giống nhau ở mọi nền. Luật HẸP: chỉ bắt ca có file khớp-không-phân-biệt mà sai hoa-thường; đường trỏ file không tồn tại và tên gói npm đều bỏ qua.',
  why:'Windows và macOS mặc định không phân biệt hoa-thường, Linux thì có. Một import lệch chạy ngon ở máy dev và chỉ chết trên CI — đúng loại "xanh ở đây, đỏ ở kia".',
  cmd:'npm run case:paths',
  trap:'Đây là cửa PHÒNG, không phải cửa chữa: lượt đo đầu tiên ra 0 vi phạm trên 490 đường import. Nhớ nó thành "đã sửa 20 test đỏ trên Linux" là nhớ sai hai chuyện khác nhau.',
  ex:'`require("./Foo")` trỏ `foo.js` ⇒ CHẶN, và in luôn tên thật trên đĩa để người sửa biết sửa thành gì.',
  src:'scripts/qa/case_paths.js', rel:['g-gate_index'] },

{ id:'g-predeploy', t:'predeploy', cat:'gate',
  def:'Chốt tiền-đẩy: dựng worktree SẠCH tại HEAD rồi mới đo bảng gate và bản đồ luật.',
  detail:'Chạy `gates:index:check` và `rule:coverage:check` trong một worktree sạch, không đo ở cây đang đứng. Coi exit 2 ở cây sạch là KHÔNG PHÁN ĐƯỢC chứ không phải đạt.',
  why:'Một bản đã ra mắt khi bảng gate đang đỏ, vì bước nghiệm thu gói không chạy cửa đó. Bản kế suýt lặp lại: cửa CÓ được chạy, nhưng ở cây có file chưa commit, nơi nó trả "không phán được" — và im lặng đó bị đọc thành "không sao".',
  cmd:'npm run predeploy',
  trap:'Đo tại chỗ cho nhanh là làm chốt gần như không bao giờ phán được, vì máy người dùng gần như luôn có file đang sửa dở.',
  ex:'Ngay lượt đầu nó chặn chính commit vừa tạo: bảng gate sinh ở cây có WIP lệch với bản sinh từ HEAD sạch.',
  src:'scripts/qa/predeploy_gate.js', rel:['g-gate_index','g-package_kit'] },

{ id:'g-canonical_check', t:'canonical:check', cat:'gate',
  def:'Canh ranh giới nguồn-sự-thật của bộ testcase: MD canonical, Excel là bản xuất.',
  detail:'Bản Markdown là nguồn; Excel là bản xuất ra cho người đọc và cho TCM. Máy chặn khi quan hệ đó bị đảo, vì đảo một lần là mất đường truy nguyên.',
  why:'Đảo ngược quan hệ đó một lần là mất đường truy nguyên: sửa Excel rồi sinh ngược ra MD thì không ai biết bản nào mới.',
  cmd:'npm run canonical:check',
  src:'scripts/qa/canonical_check.js', rel:['c-canonical'] },

{ id:'g-db_paths_check', t:'db:paths:check', cat:'gate',
  def:'Mọi đường tới DB phải đi qua client chỉ-đọc; file mở đường riêng phải có miễn trừ ghi rõ hạn rà soát.',
  detail:'Quét mọi file có thể mở kết nối DB và đòi chúng đi qua uatDbClient. File mở đường riêng phải nằm trong danh sách miễn trừ, kèm lý do và HẠN RÀ SOÁT — miễn trừ không hạn là miễn trừ vĩnh viễn.',
  why:'Một đường tắt tới DB không ai thấy là một đường ghi tiềm năng trên UAT.',
  cmd:'npm run db:paths:check',
  src:'scripts/qa/db_paths_check.js', rel:['r-uat'] },

{ id:'g-db_query', t:'db:query', cat:'gate',
  def:'Chạy MỘT câu SELECT read-only trên kho DB UAT, qua lint chặn mọi thứ không phải SELECT.',
  detail:'Đường chính thức để hỏi DB UAT: một câu SELECT, qua sql_readonly_lint. Có đường chính thức thì không ai phải tự mở đường riêng — và mọi lượt hỏi đều đi qua cùng một chỗ kiểm.',
  why:'Có một đường chính thức để hỏi DB thì không ai phải tự mở đường riêng.',
  cmd:'npm run db:query -- "<SELECT …>"',
  trap:'DB KHÔNG phải evidence, và không dựng precondition bằng DB.',
  src:'scripts/qa/db_query.js', rel:['r-uat','g-db_paths_check'] },

/* ── Lứa v2.9.5: bốn máy sinh ra từ việc đo kit mình so với một bộ plugin QA khác ── */

{ id:'g-phase1_tables', t:'phase1:tables', cat:'gate',
  def:'Sinh ba bảng đối soát cuối bộ testcase, và CHẶN khi một rule chỉ được chứng minh bằng đường thuận.',
  detail:'Ba bảng ghi vào reports/phase1-summary.md: ① rule × số TC × dương/âm/biên · ② case chiều hiển thị đã có chống lưng chưa · ③ phân bố kỹ thuật. Bảng ③ KHÔNG đếm lại mà gọi thẳng dimension_coverage.js.',
  why:'Ba bảng này trước đây do agent tự kẻ, và bảng tự kẻ hỏng theo hai đường đều im lặng: kẻ sai số, hoặc kẻ đúng rồi bộ case đổi mà bảng ở lại. Sinh từ chính bộ case thì không còn đường nào trong hai đường đó.',
  how:['Chạy vài giây, chỉ đọc test-cases/ của task.','Thêm --enforce để chặn; --check để bắt khối bị sửa tay.'],
  cmd:'npm run phase1:tables -- --enforce   ·   npm run phase1:tables:check',
  ex:'Một rule có ba case nhưng cả ba đều [Positive] ⇒ CHẶN: chỗ bug sống là đường phải bị chặn, mà đường đó chưa ai đi.',
  trap:'Máy đọc TAG và CHỮ, không hiểu nghĩa: case khai [Negative] mà thật ra đi đường thuận thì vẫn được đếm là âm. Và 0 testcase ⇒ exit 2 (KHÔNG PHÁN ĐƯỢC), không phải exit 0.',
  src:'scripts/qa/phase1_tables.js', rel:['g-dimension_coverage','g-design_gate','c-chieu-coverage','f-phase1','c-gate-real-content'] },

{ id:'g-recon_check', t:'recon:check', cat:'gate',
  def:'Bản kê màn hình dựng từ recon phải nói rõ MỖI dòng lấy từ đâu — đặc tả, hay chỉ là ảnh chụp build.',
  detail:'Đọc catalog recon của task và đòi ba thứ: nguồn trỏ về requirements/, hoặc khai thẳng dòng đó lấy từ build; và một câu tự nêu giới hạn — bản kê chụp từ build KHÔNG chứng minh build đúng đặc tả.',
  why:'Recon rất dễ biến thành tautology có hình dạng tài liệu: chụp lại màn hình đang chạy, đặt tên là "đặc tả màn", rồi lấy chính nó làm oracle. Lúc đó mọi case đều PASS, và cái PASS đó không nói gì cả.',
  cmd:'npm run recon:check',
  trap:'Cố ý KHÔNG chạy trong CI: nó đọc outputs/ của task, mà CI không có outputs/ nên lượt nào cũng exit 2. Một cửa luôn exit 2 trong CI là cửa dạy người ta bỏ qua exit 2.',
  src:'scripts/qa/recon_check.js', rel:['sk-requirements_analyzer','c-tautology','c-oracle','f-phase1'] },

{ id:'g-rule_consistency', t:'rule:consistency', cat:'gate',
  def:'Luật đổi lời thì tài liệu cũ ở lại và nói ngược luật mới — cửa này quét mọi file được track để tìm chỗ đó.',
  detail:'Đọc mệnh đề canonical khai trong .agent/config/rule_consistency.json rồi soi toàn bộ file track. Miễn trừ theo vùng cho phần lịch sử; miễn trừ theo DÒNG thì bắt buộc kèm ly_do từ 20 ký tự trở lên.',
  why:'Lớp hỏng này đã cắn ba lần trong cùng một kit: luật evidence, lệnh /check, và câu chữ step ở Phase 2. Mỗi lần đều là cùng một chuyện — có người sửa luật, không ai đi tìm những chỗ đang chép lại lời cũ.',
  how:['Chỉ đọc file trong repo, chạy được offline.','Miễn trừ CHẾT (trỏ vào chỗ không còn mâu thuẫn) được báo ra, để danh sách miễn trừ không tự phình lên.'],
  cmd:'npm run rule:consistency',
  trap:'0 mệnh đề khai trong config ⇒ exit 2, KHÔNG phải exit 0: "không có gì để gác" không đồng nghĩa với "đạt". Và grep -i không hạ chữ hoa tiếng Việt có dấu — đó là lý do phải soi bằng JS chứ không bằng một dòng grep.',
  src:'scripts/qa/rule_consistency.js', rel:['c-canonical','c-forcing-function','c-gate-real-content','g-rule_parity'] },

{ id:'g-skills_route', t:'skills:route:check', cat:'gate',
  def:'Đo xem phần mô tả của 28 skill có đủ tách bạch để chọn đúng skill từ một câu yêu cầu không.',
  detail:'Chấm điểm theo IDF trên description cộng các câu kích hoạt mẫu, chạy trên 63 ca tiếng Việt viết DIỄN Ý lại chứ không chép nguyên câu mẫu. Có sàn tự tin: điểm cao nhất mà chưa vượt sàn thì coi là không chọn được.',
  why:'skills:lint bắt được hai mô tả TRÙNG nhau, nhưng không bắt được hai mô tả KHÁC NHAU mà vẫn không tách nổi việc. Đó mới là kiểu nhập nhằng hay gặp.',
  cmd:'npm run skills:route:check',
  ex:'Sáu cặp skill dễ lẫn được khai thẳng trong fixture, để con số không đẹp lên nhờ bỏ qua đúng những ca khó.',
  trap:'ĐỌC ĐÚNG CON SỐ: đây là phép đo ĐẠI DIỆN trên từ ngữ. "98%" nghĩa là phần chữ hiện có đủ phân biệt 98% số ca trong fixture — KHÔNG phải "agent chọn đúng 98%".',
  src:'scripts/qa/skills_route.js', rel:['g-skills_lint','g-skills_index','g-skills_refcheck','f-kit-layers'] },

{ id:'g-router_check', t:'router:check', cat:'gate',
  def:'Bảng định tuyến phải phủ MỌI điểm vào, và mỗi dòng phải nói được khi nào KHÔNG dùng.',
  detail:'Mẫu số đọc từ đĩa: 13 lệnh `/` trong .claude/commands, 16 workflow trong .agent/workflows, 3 subagent trong .claude/agents. Thiếu một dòng là CHẶN. Bảng nằm ở references/router.md của skill qa_automation_engineer.',
  why:'Kit đã có ba chỗ liệt kê lệnh — CHEATSHEET, kit-map, skills INDEX — nhưng đo 29/10/2026 thì KHÔNG chỗ nào ghi "KHÔNG dùng khi". Một danh sách không ranh giới trả lời được "kit có lệnh gì", không trả lời được "lệnh nào SAI cho việc này". Chọn sai điểm vào tốn cả một lượt chạy, và lượt đó thường kết thúc bằng một kết luận nhìn rất hợp lý.',
  how:['Chỉ đọc file trong repo, chạy được offline.','Dòng mồ côi (bảng còn tên mà đĩa không còn) chỉ CẢNH BÁO: quên xoá nhỏ hơn hẳn quên thêm.'],
  cmd:'npm run router:check',
  ex:'Ô "KHÔNG dùng khi" điền dấu `-` cho đủ cũng bị chặn — sàn 25 ký tự, đo từ ô ngắn nhất đang có là 44.',
  trap:'Bản đầu khoá bảng bằng TÊN TRẦN và nó báo ĐẠT trên bảng thiếu một dòng: `rerun` tồn tại VỪA là lệnh `/rerun` VỪA là workflow `rerun.md`, nên một dòng che hai điểm vào — 31 dòng phủ 32 điểm vào mà vẫn xanh. Khoá phải gồm LOẠI, và vùng phân loại neo bằng comment máy-đọc chứ không bằng câu chữ tiêu đề.',
  src:'scripts/qa/router_check.js', rel:['g-gate_index','c-forcing-function','c-gate-real-content','g-skills_index'] },

{ id:'g-data_chain', t:'data:chain / data:chain:check', cat:'gate',
  def:'Case khai tiền đề là OUTPUT của case khác thì bộ case thành một CHUỖI — và chuỗi đó phải đứng được.',
  detail:'Đọc ô Tiền điều kiện, nhận mệnh đề có động từ dựng/tạo/khai/đã chạy xong kèm mã TC. Gác bốn đường hỏng: trỏ vào hư không, ngược thứ tự, vòng, và nguồn FAILED mà case phụ thuộc PASSED. Phép kiểm cuối cần testcase-status.json, và cửa tự tìm file đó ở đường dẫn chuẩn của task.',
  why:'Đo 29/10/2026 trên bộ case thật: 9 ca khai phụ thuộc như vậy, và không máy nào trong kit nhìn thấy. Đường hỏng đắt nhất là nguồn chưa dựng mà vẫn chấm tiếp: phép đo chạy trên một tình huống KHÔNG TỒN TẠI, và lớp đó đã sinh ra 2 product_bug bịa trong một phiên.',
  how:['Chỉ đọc artefact local, chạy được offline.','Nằm trong bó phase1:check và phase2:check chứ không thêm một dòng prompt mới — prompt:budget cấm nâng ngưỡng.'],
  cmd:'npm run data:chain   ·   npm run data:chain:check',
  ex:'Lượt chạy ĐẦU TIÊN trên bộ CSDL-9004 bắt được một ca thật: TC_063 khai dựng ở TC_075, nhưng TC_075 nằm SAU nó trong file (dòng 80 so với dòng 92).',
  trap:'Ranh giới nằm ở ĐỘNG TỪ, không ở việc có tên TC. Bộ case thật còn 16 lượt trỏ TC khác nhưng là trích dẫn để đọc — "đã kiểm ở TC_045", "SQL ở TC_088". Gác cả 25 lượt là gác phần lớn dương tính giả, rồi người ta tắt cửa chứ không sửa theo nó. Và máy chỉ thấy chuỗi đã KHAI: case phụ thuộc mà không khai thì vẫn là phần chấm tay.',
  src:'scripts/qa/data_chain_check.js', rel:['sk-test_data_generator','sk-automation_reviewer','g-phase_check','c-gate-real-content'] },

{ id:'g-parity_check', t:'parity:check', cat:'gate',
  def:'Gác chính bảng nghiệm thu A_PARITY: không dòng nào được để trống, và mọi tên máy phải có thật.',
  detail:'Mỗi dòng phải kết về một trong ba trạng thái — đã làm kèm máy gác, cố ý không port kèm lý do, hoặc đã làm phần tài liệu nhưng chưa có máy. Cửa còn đòi đủ ba khối, và chặn cả khối CHƯA CÓ MÁY rỗng.',
  why:'Bảng nghiệm thu là lớp dẫn xuất viết tay, và mọi bảng viết tay trong kit đều đã trôi ít nhất một lần. Bảng nghiệm thu trôi thì tệ hơn bảng thường: nó là thứ người ta đọc để tin rằng đợt làm đã xong.',
  cmd:'npm run parity:check',
  ex:'Khối CHƯA CÓ MÁY rỗng cũng bị chặn — một đợt làm không còn chỗ nào thiếu máy là lời khai đáng ngờ hơn đáng mừng.',
  trap:'Lượt chạy đầu bắt được hai lỗi của chính tài liệu: phần mở đầu dùng đúng cụm từ mà luật cấm nên nó tự chặn mình, và bảng nhắc một tên máy không tồn tại. Đã đổi lời chứ không thêm miễn trừ. Giới hạn: máy đọc ký hiệu và tên máy, KHÔNG đọc nghĩa.',
  src:'scripts/qa/parity_check.js', rel:['c-canonical','c-forcing-function','c-gate-real-content','g-library_drift'] },

{ id:'g-exec_tally', t:'exec:tally / exec:tally:check', cat:'gate',
  def:'Số trong execution-summary.md phải TRUY được về một sổ verdict có tên — máy sinh khối số, rồi gác chính khối đó.',
  detail:'Đọc sổ verdict mới nhất của task, sinh một khối có mốc ghi rõ sổ nào, mốc thời gian nào, runId nào, và bao nhiêu case mỗi verdict. Phần văn xuôi chỉ được ĐỐI CHIẾU và CẢNH BÁO, không chặn, và số khai xấp xỉ dạng ~28 được tôn trọng.',
  why:'automation_reviewer từng khai chuyện này là chỗ máy KHÔNG phán được, với lý lẽ bản summary do người viết. Đo lại 29/10/2026 thì lý lẽ đó đúng một nửa: phần KỂ thì máy không chấm được, nhưng phần SỐ thì truy được về một tệp có tên. Và số lệch thật — CSDL-9004 summary ghi PASS 31 trong khi sổ có PASSED 140.',
  how:['Nằm trong bó phase2:check, không thêm dòng prompt nào.','Lệch KHÔNG tự nghĩa là sai: sổ có thể là của một lô, còn summary kể cả đợt — nhưng chênh phải được giải thích bằng chữ.'],
  cmd:'npm run exec:tally   ·   npm run exec:tally:check',
  ex:'Bốn execution-summary thật ghi số theo BỐN khuôn khác nhau — một văn xuôi, ba bảng với tiêu đề khác nhau. Nên một cửa dò khuôn chuẩn chỉ chạy được trên một phần tư, và thiết kế đúng là máy SINH khối rồi gác khối.',
  trap:'Bản đầu đọc MÃ TESTCASE thành số đếm: TC_199 PASS bị tính là 199 PASS. Phải siết HAI lần — lần một chặn chữ và gạch dưới đứng trước, lần hai chặn thêm dấu gạch chéo, vì TC_184/185/217 PASS là một danh sách mã. Đo được 6 → 5 → 4 cảnh báo, và 4 cái còn lại đã soi ngữ cảnh là thật.',
  src:'scripts/qa/exec_summary_tally.js', rel:['g-phase_check','sk-run_report_reader','g-result_ledger','c-gate-real-content'] },

{ id:'g-recon_passive', t:'recon:passive', cat:'gate',
  def:'Recon chỉ được QUAN SÁT, không được DÒ — và phải vẫn còn đang nghe.',
  detail:'Chặn 7 kiểu tự gửi request trong bộ máy recon: fetch, axios, page.request.*, XMLHttpRequest, $.ajax, module http/https, và spawn curl/wget. Điều hướng bằng goto và đọc DOM bằng page.evaluate thì được phép — chặn hai thứ đó là biến recon thành không làm được gì.',
  why:'Recon sinh ra bản kê màn và API, rồi bản kê đó được dùng làm NGUỒN để viết case. Một endpoint mình tự gọi bằng fetch trả 200 không nói gì về việc UI có gọi nó, gọi với payload nào, hay người dùng có đường nào tới đó — nhưng nó TRÔNG như một phát hiện. Đó là đường ngắn nhất để một bản kê recon chứa thứ sản phẩm không có.',
  how:['Chỉ đọc file trong repo, chạy được ở CI.','Chiều thứ hai mới chống được cửa rỗng: phải còn ít nhất một page.on(response) — xoá sạch listener thì recon không quan sát gì nữa, mà phép kiểm thứ nhất vẫn xanh.'],
  cmd:'npm run recon:passive',
  ex:'Đo 29/10/2026 trên 8 file của scripts/qa/discovery: 5 chỗ nghe thụ động, 0 chỗ tự gửi request. Cửa nổ 0 lượt, nên spec có đối chứng dương cho CẢ BẢY mẫu.',
  trap:'Hai mẫu phải đọc trên bản CÒN ruột chuỗi vì thứ chúng tìm nằm TRONG chuỗi: require(https) và spawnSync(curl). Bản đầu cho cả bảy mẫu đọc trên bản đã làm trắng chuỗi nên hai mẫu đó không bao giờ nổ — và một mẫu hỏng chỉ lộ ra vì đối chứng dương của nó đỏ, mẫu còn lại chưa bị phát hiện vì vòng lặp của spec dừng trước đó.',
  src:'scripts/qa/recon_passive.js', rel:['sk-requirements_analyzer','g-recon_check','c-tautology','c-gate-real-content'] },

];
